  "//\n"
  "// SYMBOL \"flip\"\n"
  "inline\n"
  "casadi_int casadi_flip(casadi_int* corner, casadi_int ndim) {\n"
  "  casadi_int i;\n"
  "  for (i=0; i<ndim; ++i) {\n"
  "    if (corner[i]) {\n"
  "      corner[i]=0;\n"
  "    } else {\n"
  "      corner[i]=1;\n"
  "      return 1;\n"
  "    }\n"
  "  }\n"
  "  return 0;\n"
  "}\n";

