  "//\n"
  "// SYMBOL \"file_slurp\"\n"
  "template <typename T1>\n"
  "int casadi_file_slurp(const char* fname, casadi_int n, T1* x) {\n"
  "  casadi_int i;\n"
  "  FILE *fp;\n"
  "  fp = fopen(fname, \"r\");\n"
  "  if (!fp) return 1;\n"
  "  for (i=0;i<n;++i) {\n"
  "    if (fscanf(fp, \"%lg\", x++)<=0) return 2;\n"
  "  }\n"
  "  fclose(fp);\n"
  "  return 0;\n"
  "}\n";

