  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"mv\"\n"
  "template<typename T1>\n"
  "void casadi_mv(const T1* x, const casadi_int* sp_x, const T1* y, T1* z, casadi_int tr) {\n"
  "  casadi_int ncol_x, i, el;\n"
  "  const casadi_int *colind_x, *row_x;\n"
  "  if (!x || !y || !z) return;\n"
  "  // Get sparsities\n"
  "  ncol_x = sp_x[1];\n"
  "  colind_x = sp_x+2; row_x = sp_x + 2 + ncol_x+1;\n"
  "  if (tr) {\n"
  "    // loop over the columns of x\n"
  "    for (i=0; i<ncol_x; ++i) {\n"
  "      // loop over the non-zeros of x\n"
  "      for (el=colind_x[i]; el<colind_x[i+1]; ++el) {\n"
  "        z[i] += x[el] * y[row_x[el]];\n"
  "      }\n"
  "    }\n"
  "  } else {\n"
  "    // loop over the columns of x\n"
  "    for (i=0; i<ncol_x; ++i) {\n"
  "      // loop over the non-zeros of x\n"
  "      for (el=colind_x[i]; el<colind_x[i+1]; ++el) {\n"
  "        z[row_x[el]] += x[el] * y[i];\n"
  "      }\n"
  "    }\n"
  "  }\n"
  "}\n";

const char* casadi_trilsolve_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"trilsolve\"\n"
  "template<typename T1>\n"
  "void casadi_trilsolve(const casadi_int* sp_a, const T1* nz_a, T1* x, int tr, int unity,\n"
  "    casadi_int nrhs) {\n"
  "  // Local variables\n"
  "  casadi_int nrow, ncol, r, c, k, rhs;\n"
  "  const casadi_int *colind, *row;\n"
  "  // Extract sparsity\n"
  "  nrow = sp_a[0];\n"
  "  ncol = sp_a[1];\n"
  "  colind = sp_a + 2;\n"
  "  row = colind + ncol + 1;\n"
  "  // For all right hand sides\n"
  "  for (rhs = 0; rhs < nrhs; ++rhs) {\n"
  "    if (unity) {\n"
  "      if (tr) {\n"
  "        // Backward substitution\n"
  "        for (c = ncol; c-- > 0; ) {\n"
  "          for (k = colind[c + 1]; k-- > colind[c]; ) {\n"
  "            x[c] += nz_a[k] * x[row[k]];\n"
  "          }\n"
  "        }\n"
  "      } else {\n"
  "        // Forward substitution\n"
  "        for (c = 0; c < ncol; ++c) {\n"
  "          for (k = colind[c]; k < colind[c+1]; ++k) {\n"
  "            x[row[k]] += nz_a[k] * x[c];\n"
  "          }\n"
  "        }\n"
  "      }\n"
  "    } else {\n"
  "      if (tr) {\n"
  "        // Backward substitution\n"
  "        for (c = ncol; c-- > 0; ) {\n"
  "          for (k = colind[c + 1]; k-- > colind[c]; ) {\n"
  "            r = row[k];\n"
  "            if (r == c) {\n"
  "              x[c] /= nz_a[k];\n"
  "            } else {\n"
  "              x[c] -= nz_a[k] * x[r];\n"
  "            }\n"
  "          }\n"
  "        }\n"
  "      } else {\n"
  "        // Forward substitution\n"
  "        for (c = 0; c < ncol; ++c) {\n"
  "          for (k = colind[c]; k < colind[c+1]; ++k) {\n"
  "            r = row[k];\n"
  "            if (r == c) {\n"
  "              x[r] /= nz_a[k];\n"
  "            } else {\n"
  "              x[r] -= nz_a[k] * x[c];\n"
  "            }\n"
  "          }\n"
  "        }\n"
  "      }\n"
  "    }\n"
  "    // Next right-hand-side\n"
  "    x += nrow;\n"
  "  }\n"
  "}\n";

