  "template<typename T1>\n"
  "void casadi_triusolve(const casadi_int* sp_a, const T1* nz_a, T1* x, int tr, int unity,\n"
  "    casadi_int nrhs) {\n"
  "  // Local variables\n"
  "  casadi_int nrow, ncol, r, c, k, rhs;\n"
  "  const casadi_int *colind, *row;\n"
  "  // Extract sparsity\n"
  "  nrow = sp_a[0];\n"
  "  ncol = sp_a[1];\n"
  "  colind = sp_a + 2;\n"
  "  row = colind + ncol + 1;\n"
  "  // For all right hand sides\n"
  "  for (rhs = 0; rhs < nrhs; ++rhs) {\n"
  "    if (unity) {\n"
  "      if (tr) {\n"
  "        // Forward substitution\n"
  "        for (c = 0; c < ncol; ++c) {\n"
  "          for (k = colind[c]; k < colind[c+1]; ++k) {\n"
  "            x[c] += nz_a[k] * x[row[k]];\n"
  "          }\n"
  "        }\n"
  "      } else {\n"
  "        // Backward substitution\n"
  "        for (c = ncol; c-- > 0; ) {\n"
  "          for (k = colind[c + 1]; k-- > colind[c]; ) {\n"
  "            x[row[k]] += nz_a[k] * x[c];\n"
  "          }\n"
  "        }\n"
  "      }\n"
  "    } else {\n"
  "      if (tr) {\n"
  "        // Forward substitution\n"
  "        for (c = 0; c < ncol; ++c) {\n"
  "          for (k = colind[c]; k < colind[c+1]; ++k) {\n"
  "            r = row[k];\n"
  "            if (r == c) {\n"
  "              x[c] /= nz_a[k];\n"
  "            } else {\n"
  "              x[c] -= nz_a[k] * x[r];\n"
  "            }\n"
  "          }\n"
  "        }\n"
  "      } else {\n"
  "        // Backward substitution\n"
  "        for (c = ncol; c-- > 0; ) {\n"
  "          for (k = colind[c + 1]; k-- > colind[c]; ) {\n"
  "            r = row[k];\n"
  "            if (r == c) {\n"
  "              x[r] /= nz_a[k];\n"
  "            } else {\n"
  "              x[r] -= nz_a[k] * x[c];\n"
  "            }\n"
  "          }\n"
  "        }\n"
  "      }\n"
  "    }\n"
  "    // Next right-hand-side\n"
  "    x += nrow;\n"
  "  }\n"
  "}\n";

