  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"norm_1\"\n"
  "template<typename T1>\n"
  "T1 casadi_norm_1(casadi_int n, const T1* x) {\n"
  "  casadi_int i;\n"
  "  T1 ret = 0;\n"
  "  if (x) {\n"
  "    for (i=0; i<n; ++i) ret += fabs(*x++);\n"
  "  }\n"
  "  return ret;\n"
  "}\n";

