  "//\n"
  "// SYMBOL \"masked_norm_inf\"\n"
  "template<typename T1>\n"
  "T1 casadi_masked_norm_inf(casadi_int n, const T1* x, const casadi_int* mask) {\n"
  "  casadi_int i;\n"
  "  T1 ret = 0;\n"
  "// C-REPLACE \"fmax\" \"casadi_fmax\"\n"
  "  for (i=0; i<n; ++i) {\n"
  "    if (mask[i]) {\n"
  "      ret = fmax(ret, fabs(x[i]));\n"
  "    }\n"
  "  }\n"
  "  return ret;\n"
  "}\n";

