  "//\n"
  "// SYMBOL \"swap\"\n"
  "template<typename T1>\n"
  "void casadi_swap(casadi_int n, T1* x, casadi_int inc_x, T1* y, casadi_int inc_y) {\n"
  "  T1 t;\n"
  "  casadi_int i;\n"
  "  for (i=0; i<n; ++i) {\n"
  "    t = *x;\n"
  "    *x = *y;\n"
  "    *y = t;\n"
  "    x += inc_x;\n"
  "    y += inc_y;\n"
  "  }\n"
  "}\n";

