  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// C-REPLACE \"fmin\" \"casadi_fmin\"\n"
  "// C-REPLACE \"fmax\" \"casadi_fmax\"\n"
  "// C-REPLACE \"std::numeric_limits<T1>::min()\" \"casadi_real_min\"\n"
  "// C-REPLACE \"std::numeric_limits<T1>::infinity()\" \"casadi_inf\"\n"
  "// C-REPLACE \"static_cast<int>\" \"(int) \"\n"
  "// C-REPLACE \"casadi_qp_prob<T1>\" \"struct casadi_qp_prob\"\n"
  "// C-REPLACE \"casadi_qp_data<T1>\" \"struct casadi_qp_data\"\n"
  "// SYMBOL \"qrqp_prob\"\n"
  "template<typename T1>\n"
  "struct casadi_qrqp_prob {\n"
  "  const casadi_qp_prob<T1>* qp;\n"
  "  // Sparsity patterns\n"
  "  const casadi_int *sp_at, *sp_kkt;\n"
  "  // Symbolic QR factorization\n"
  "  const casadi_int *prinv, *pc, *sp_v, *sp_r;\n"
  "  // Smallest nonzero number\n"
  "  T1 dmin;\n"
  "  // Infinity\n"
  "  T1 inf;\n"
  "  // Smallest multiplier treated as inactive for the initial active set\n"
  "  T1 min_lam;\n"
  "  // Maximum number of iterations\n"
  "  casadi_int max_iter;\n"
  "  // Primal and dual error tolerance\n"
  "  T1 constr_viol_tol, dual_inf_tol;\n"
  "};\n"
  "// C-REPLACE \"casadi_qrqp_prob<T1>\" \"struct casadi_qrqp_prob\"\n"
  "// SYMBOL \"qrqp_setup\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_setup(casadi_qrqp_prob<T1>* p) {\n"
  "  p->dmin = std::numeric_limits<T1>::min();\n"
  "  p->inf = std::numeric_limits<T1>::infinity();\n"
  "  p->min_lam = 0;\n"
  "  p->max_iter = 1000;\n"
  "  p->constr_viol_tol = 1e-8;\n"
  "  p->dual_inf_tol = 1e-8;\n"
  "}\n"
  "// SYMBOL \"qrqp_flag_t\"\n"
  "typedef enum {\n"
  "  QP_SUCCESS,\n"
  "  QP_MAX_ITER,\n"
  "  QP_NO_SEARCH_DIR,\n"
  "  QP_PRINTING_ERROR\n"
  "} casadi_qrqp_flag_t;\n"
  "// SYMBOL \"qrqp_data\"\n"
  "template<typename T1>\n"
  "struct casadi_qrqp_data {\n"
  "  // Problem structure\n"
  "  const casadi_qrqp_prob<T1>* prob;\n"
  "  // Problem structure\n"
  "  casadi_qp_data<T1>* qp;\n"
  "  // Cost\n"
  "  T1 f;\n"
  "  // Solver status\n"
  "  casadi_qrqp_flag_t status;\n"
  "  // Vectors\n"
  "  T1 *lbz, *ubz, *z, *infeas, *tinfeas, *sens, *lam, *w, *dz, *dlam;\n"
  "  casadi_int *iw, *neverzero, *neverlower, *neverupper, *lincomb;\n"
  "  // Numeric QR factorization\n"
  "  T1 *nz_at, *nz_kkt, *beta, *nz_v, *nz_r;\n"
  "  // Message buffer\n"
  "  const char *msg;\n"
  "  // Message index\n"
  "  casadi_int msg_ind;\n"
  "  // Stepsize\n"
  "  T1 tau;\n"
  "  // Singularity\n"
  "  casadi_int sing;\n"
  "  // Do we already have a search direction?\n"
  "  int has_search_dir;\n"
  "  // Smallest diagonal value for the QR factorization\n"
  "  T1 mina;\n"
  "  casadi_int imina;\n"
  "  // Primal and dual error, corresponding index\n"
  "  T1 pr, du, epr, edu;\n"
  "  casadi_int ipr, idu;\n"
  "  // Pending active-set change\n"
  "  casadi_int index, sign;\n"
  "  // Feasibility restoration active-set change\n"
  "  casadi_int r_index, r_sign;\n"
  "  // Iteration\n"
  "  casadi_int iter;\n"
  "};\n"
  "// C-REPLACE \"casadi_qrqp_data<T1>\" \"struct casadi_qrqp_data\"\n"
  "// SYMBOL \"qrqp_work\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_work(const casadi_qrqp_prob<T1>* p, casadi_int* sz_arg, casadi_int* sz_res,\n"
  "    casadi_int* sz_iw, casadi_int* sz_w) {\n"
  "  // Local variables\n"
  "  casadi_int nnz_a, nnz_kkt, nnz_v, nnz_r;\n"
  "  casadi_qp_work(p->qp, sz_arg, sz_res, sz_iw, sz_w);\n"
  "  // Get matrix number of nonzeros\n"
  "  nnz_a = p->qp->sp_a[2+p->qp->sp_a[1]];\n"
  "  nnz_kkt = p->sp_kkt[2+p->sp_kkt[1]];\n"
  "  nnz_v = p->sp_v[2+p->sp_v[1]];\n"
  "  nnz_r = p->sp_r[2+p->sp_r[1]];\n"
  "  // Temporary work vectors\n"
  "  *sz_w = casadi_max(*sz_w, p->qp->nz); // casadi_project, tau memory\n"
  "  *sz_iw = casadi_max(*sz_iw, p->qp->nz); // casadi_trans, tau type, allzero\n"
  "  *sz_w = casadi_max(*sz_w, 2*p->qp->nz); // casadi_qr\n"
  "  // Persistent work vectors\n"
  "  *sz_w += nnz_kkt; // kkt\n"
  "  *sz_w += p->qp->nz; // z=[xk,gk]\n"
  "  *sz_w += p->qp->nz; // lbz\n"
  "  *sz_w += p->qp->nz; // ubz\n"
  "  *sz_w += p->qp->nz; // lam\n"
  "  *sz_w += p->qp->nz; // dz\n"
  "  *sz_w += p->qp->nz; // dlam\n"
  "  *sz_w += casadi_max(nnz_v+nnz_r, nnz_kkt); // [v,r] or trans(kkt)\n"
  "  *sz_w += p->qp->nz; // beta\n"
  "  *sz_w += nnz_a; // trans(a)\n"
  "  *sz_w += p->qp->nx; // infeas\n"
  "  *sz_w += p->qp->nx; // tinfeas\n"
  "  *sz_w += p->qp->nz; // sens\n"
  "  *sz_iw += p->qp->nz; // neverzero\n"
  "  *sz_iw += p->qp->nz; // neverupper\n"
  "  *sz_iw += p->qp->nz; // neverlower\n"
  "  *sz_iw += p->qp->nz; // lincomb\n"
  "}\n"
  "// SYMBOL \"qrqp_init\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_init(casadi_qrqp_data<T1>* d, casadi_int** iw, T1** w) {\n"
  "  // Local variables\n"
  "  casadi_int nnz_a, nnz_kkt, nnz_v, nnz_r;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Get matrix number of nonzeros\n"
  "  nnz_a = p->qp->sp_a[2+p->qp->sp_a[1]];\n"
  "  nnz_kkt = p->sp_kkt[2+p->sp_kkt[1]];\n"
  "  nnz_v = p->sp_v[2+p->sp_v[1]];\n"
  "  nnz_r = p->sp_r[2+p->sp_r[1]];\n"
  "  d->nz_kkt = *w; *w += nnz_kkt;\n"
  "  d->z = *w; *w += p->qp->nz;\n"
  "  d->lbz = *w; *w += p->qp->nz;\n"
  "  d->ubz = *w; *w += p->qp->nz;\n"
  "  d->lam = *w; *w += p->qp->nz;\n"
  "  d->dz = *w; *w += p->qp->nz;\n"
  "  d->dlam = *w; *w += p->qp->nz;\n"
  "  d->nz_v = *w; *w += casadi_max(nnz_v+nnz_r, nnz_kkt);\n"
  "  d->beta = *w; *w += p->qp->nz;\n"
  "  d->nz_at = *w; *w += nnz_a;\n"
  "  d->infeas = *w; *w += p->qp->nx;\n"
  "  d->tinfeas = *w; *w += p->qp->nx;\n"
  "  d->sens = *w; *w += p->qp->nz;\n"
  "  d->neverzero = *iw; *iw += p->qp->nz;\n"
  "  d->neverupper = *iw; *iw += p->qp->nz;\n"
  "  d->neverlower = *iw; *iw += p->qp->nz;\n"
  "  d->lincomb = *iw; *iw += p->qp->nz;\n"
  "  d->w = *w;\n"
  "  d->iw = *iw;\n"
  "  d->nz_r = d->nz_v + nnz_v;\n"
  "}\n"
  "// SYMBOL \"qrqp_reset\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_reset(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Reset variables corresponding to previous iteration\n"
  "  d->msg = 0;\n"
  "  d->tau = 0.;\n"
  "  d->sing = 0;\n"
  "  // Correct lam if needed, determine permitted signs\n"
  "  for (i=0; i<p->qp->nz; ++i) {\n"
  "    // Permitted signs for lam\n"
  "    d->neverzero[i] = d->lbz[i] == d->ubz[i];\n"
  "    d->neverupper[i] = d->ubz[i] == p->inf;\n"
  "    d->neverlower[i] = d->lbz[i] == -p->inf;\n"
  "    if (d->neverzero[i] && d->neverupper[i] && d->neverlower[i]) return 1;\n"
  "    // Small enough lambdas are treated as inactive\n"
  "    if (!d->neverzero[i] && fabs(d->lam[i]) < p->min_lam) d->lam[i] = 0.;\n"
  "    // Prevent illegal active sets\n"
  "    if (d->neverzero[i] && d->lam[i] == 0.) {\n"
  "      d->lam[i] = d->neverupper[i]\n"
  "                || d->z[i]-d->lbz[i] <= d->ubz[i]-d->z[i] ? -p->dmin : p->dmin;\n"
  "    } else if (d->neverupper[i] && d->lam[i]>0.) {\n"
  "      d->lam[i] = d->neverzero[i] ? -p->dmin : 0.;\n"
  "    } else if (d->neverlower[i] && d->lam[i]<0.) {\n"
  "      d->lam[i] = d->neverzero[i] ? p->dmin : 0.;\n"
  "    }\n"
  "  }\n"
  "  // Transpose A\n"
  "  casadi_trans(d->qp->a, p->qp->sp_a, d->nz_at, p->sp_at, d->iw);\n"
  "  // No pending active-set change\n"
  "  d->index = -2;\n"
  "  d->sign = 0;\n"
  "  // No restoration index\n"
  "  d->r_index = -2;\n"
  "  d->r_sign = 0;\n"
  "  // Reset iteration counter\n"
  "  d->iter = 0;\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_pr\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_pr(casadi_qrqp_data<T1>* d) {\n"
  "  // Calculate largest constraint violation\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  d->pr = 0;\n"
  "  d->ipr = -1;\n"
  "  for (i=0; i<p->qp->nz; ++i) {\n"
  "    if (d->z[i] > d->ubz[i]+d->pr) {\n"
  "      d->pr = d->z[i]-d->ubz[i];\n"
  "      d->ipr = i;\n"
  "    } else if (d->z[i] < d->lbz[i]-d->pr) {\n"
  "      d->pr = d->lbz[i]-d->z[i];\n"
  "      d->ipr = i;\n"
  "    }\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_du\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_du(casadi_qrqp_data<T1>* d) {\n"
  "  // Calculate largest constraint violation\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  d->du = 0;\n"
  "  d->idu = -1;\n"
  "  for (i=0; i<p->qp->nx; ++i) {\n"
  "    if (d->infeas[i] > d->du) {\n"
  "      d->du = d->infeas[i];\n"
  "      d->idu = i;\n"
  "    } else if (d->infeas[i] < -d->du) {\n"
  "      d->du = -d->infeas[i];\n"
  "      d->idu = i;\n"
  "    }\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_du_check\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_du_check(casadi_qrqp_data<T1>* d, casadi_int i) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  T1 new_du;\n"
  "  const casadi_int *at_colind, *at_row;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // AT sparsity\n"
  "  at_colind = p->sp_at + 2;\n"
  "  at_row = at_colind + p->qp->na + 1;\n"
  "  // Maximum infeasibility from setting from setting lam[i]=0\n"
  "  if (i<p->qp->nx) {\n"
  "    new_du = fabs(d->infeas[i]-d->lam[i]);\n"
  "  } else {\n"
  "    new_du = 0.;\n"
  "    for (k=at_colind[i-p->qp->nx]; k<at_colind[i-p->qp->nx+1]; ++k) {\n"
  "      new_du = fmax(new_du, fabs(d->infeas[at_row[k]]-d->nz_at[k]*d->lam[i]));\n"
  "    }\n"
  "  }\n"
  "  return new_du <= d->du;\n"
  "}\n"
  "// SYMBOL \"qrqp_du_index\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_du_index(casadi_qrqp_data<T1>* d) {\n"
  "  // Try to improve dual feasibility by removing a constraint\n"
  "  // Local variables\n"
  "  casadi_int i, s;\n"
  "  T1 best_sens;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Find the best lam[i] to make zero\n"
  "  d->index = -1;\n"
  "  best_sens = -1;\n"
  "  for (i = 0; i < p->qp->nz; ++i) {\n"
  "    // Skip if no dual infeasibility sensitivity\n"
  "    if (d->sens[i] == 0.) continue;\n"
  "    // Is the constraint enforced?\n"
  "    if (d->lam[i] == 0) {\n"
  "      // We're enforcing constraints\n"
  "      s = d->sens[i] > 0 ? 1 : -1;\n"
  "      // Make sure that enforcing the constraint is possible\n"
  "      if (s > 0 ? d->neverupper[i] : d->neverlower[i]) continue;\n"
  "    } else {\n"
  "      // We're removing constraints\n"
  "      s = 0;\n"
  "      // Make sure that it's a constraint that can be removed\n"
  "      if (d->neverzero[i]) continue;\n"
  "      // If variable influences du, make sure sign is right\n"
  "      if (d->lam[i] > 0. ? d->sens[i] > 0. : d->sens[i] < 0.) continue;\n"
  "      // Skip if maximum infeasibility increases\n"
  "      if (!casadi_qrqp_du_check(d, i)) continue;\n"
  "    }\n"
  "    // Check if best so far\n"
  "    if (fabs(d->sens[i]) > best_sens) {\n"
  "      best_sens = fabs(d->sens[i]);\n"
  "      d->index = i;\n"
  "      d->sign = s;\n"
  "    }\n"
  "  }\n"
  "  // Accept, if any\n"
  "  if (d->index >= 0) {\n"
  "    if (d->sign > 0) {\n"
  "      d->msg = \"Enforced ubz to reduce |du|\";\n"
  "    } else if (d->sign < 0) {\n"
  "      d->msg = \"Enforced lbz to reduce |du|\";\n"
  "    } else if (d->lam[d->index] > 0) {\n"
  "      d->msg = \"Dropped ubz to reduce |du|\";\n"
  "    } else {\n"
  "      d->msg = \"Dropped lbz to reduce |du|\";\n"
  "    }\n"
  "    d->msg_ind = d->index;\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_pr_index\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_pr_index(casadi_qrqp_data<T1>* d) {\n"
  "  // Try to improve primal feasibility by adding a constraint\n"
  "  if (d->lam[d->ipr] == 0.) {\n"
  "    // Add the most violating constraint\n"
  "    if (d->z[d->ipr] < d->lbz[d->ipr]) {\n"
  "      d->sign = -1;\n"
  "      d->msg = \"Added lbz to reduce |pr|\";\n"
  "    } else {\n"
  "      d->sign = 1;\n"
  "      d->msg = \"Added ubz to reduce |pr|\";\n"
  "    }\n"
  "    d->msg_ind = d->ipr;\n"
  "    d->index = d->ipr;\n"
  "  } else {\n"
  "    // No improvement possible\n"
  "    d->index = -1;\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_kkt\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_kkt(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i, k;\n"
  "  const casadi_int *h_colind, *h_row, *a_colind, *a_row, *at_colind, *at_row,\n"
  "                   *kkt_colind, *kkt_row;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Extract sparsities\n"
  "  a_row = (a_colind = p->qp->sp_a+2) + p->qp->nx + 1;\n"
  "  at_row = (at_colind = p->sp_at+2) + p->qp->na + 1;\n"
  "  h_row = (h_colind = p->qp->sp_h+2) + p->qp->nx + 1;\n"
  "  kkt_row = (kkt_colind = p->sp_kkt+2) + p->qp->nz + 1;\n"
  "  // Reset w to zero\n"
  "  casadi_clear(d->w, p->qp->nz);\n"
  "  // Loop over rows of the (transposed) KKT\n"
  "  for (i=0; i<p->qp->nz; ++i) {\n"
  "    // Copy row of KKT to w\n"
  "    if (i<p->qp->nx) {\n"
  "      if (d->lam[i]==0) {\n"
  "        for (k=h_colind[i]; k<h_colind[i+1]; ++k) d->w[h_row[k]] = d->qp->h[k];\n"
  "        for (k=a_colind[i]; k<a_colind[i+1]; ++k) d->w[p->qp->nx+a_row[k]] = d->qp->a[k];\n"
  "      } else {\n"
  "        d->w[i] = 1.;\n"
  "      }\n"
  "    } else {\n"
  "      if (d->lam[i]==0) {\n"
  "        d->w[i] = -1.;\n"
  "      } else {\n"
  "        for (k=at_colind[i-p->qp->nx]; k<at_colind[i-p->qp->nx+1]; ++k) {\n"
  "          d->w[at_row[k]] = d->nz_at[k];\n"
  "        }\n"
  "      }\n"
  "    }\n"
  "    // Copy row to KKT, zero out w\n"
  "    for (k=kkt_colind[i]; k<kkt_colind[i+1]; ++k) {\n"
  "      d->nz_kkt[k] = d->w[kkt_row[k]];\n"
  "      d->w[kkt_row[k]] = 0;\n"
  "    }\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_kkt_vector\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_kkt_vector(casadi_qrqp_data<T1>* d, T1* kkt_i, casadi_int i) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  const casadi_int *h_colind, *h_row, *a_colind, *a_row, *at_colind, *at_row;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Extract sparsities\n"
  "  a_row = (a_colind = p->qp->sp_a+2) + p->qp->nx + 1;\n"
  "  at_row = (at_colind = p->sp_at+2) + p->qp->na + 1;\n"
  "  h_row = (h_colind = p->qp->sp_h+2) + p->qp->nx + 1;\n"
  "  // Reset kkt_i to zero\n"
  "  casadi_clear(kkt_i, p->qp->nz);\n"
  "  // Copy sparse entries\n"
  "  if (i<p->qp->nx) {\n"
  "    for (k=h_colind[i]; k<h_colind[i+1]; ++k) kkt_i[h_row[k]] = d->qp->h[k];\n"
  "    for (k=a_colind[i]; k<a_colind[i+1]; ++k) kkt_i[p->qp->nx+a_row[k]] = d->qp->a[k];\n"
  "  } else {\n"
  "    for (k=at_colind[i-p->qp->nx]; k<at_colind[i-p->qp->nx+1]; ++k) {\n"
  "      kkt_i[at_row[k]] = -d->nz_at[k];\n"
  "    }\n"
  "  }\n"
  "  // Add diagonal entry\n"
  "  kkt_i[i] -= 1.;\n"
  "}\n"
  "// SYMBOL \"qrqp_kkt_dot\"\n"
  "template<typename T1>\n"
  "T1 casadi_qrqp_kkt_dot(casadi_qrqp_data<T1>* d, const T1* v, casadi_int i) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  const casadi_int *h_colind, *h_row, *a_colind, *a_row, *at_colind, *at_row;\n"
  "  T1 r;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Extract sparsities\n"
  "  a_row = (a_colind = p->qp->sp_a + 2) + p->qp->nx + 1;\n"
  "  at_row = (at_colind = p->sp_at + 2) + p->qp->na + 1;\n"
  "  h_row = (h_colind = p->qp->sp_h + 2) + p->qp->nx + 1;\n"
  "  // Scalar product with the diagonal\n"
  "  r = v[i];\n"
  "  // Scalar product with the sparse entries\n"
  "  if (i < p->qp->nx) {\n"
  "    for (k=h_colind[i]; k<h_colind[i+1]; ++k) r -= v[h_row[k]] * d->qp->h[k];\n"
  "    for (k=a_colind[i]; k<a_colind[i+1]; ++k) r -= v[p->qp->nx+a_row[k]] * d->qp->a[k];\n"
  "  } else {\n"
  "    for (k=at_colind[i-p->qp->nx]; k<at_colind[i-p->qp->nx+1]; ++k) {\n"
  "      r += v[at_row[k]] * d->nz_at[k];\n"
  "    }\n"
  "  }\n"
  "  return r;\n"
  "}\n"
  "// SYMBOL \"qrqp_kkt_residual\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_kkt_residual(casadi_qrqp_data<T1>* d, T1* r) {\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  for (i=0; i<p->qp->nz; ++i) {\n"
  "    if (d->lam[i]>0.) {\n"
  "      r[i] = d->ubz[i]-d->z[i];\n"
  "    } else if (d->lam[i]<0.) {\n"
  "      r[i] = d->lbz[i]-d->z[i];\n"
  "    } else if (i<p->qp->nx) {\n"
  "      r[i] = d->lam[i]-d->infeas[i];\n"
  "    } else {\n"
  "      r[i] = d->lam[i];\n"
  "    }\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_zero_blocking\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_zero_blocking(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i;\n"
  "  T1 dz_max = 0;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Look for violated constraints that are not improving\n"
  "  for (i = 0; i < p->qp->nz; ++i) {\n"
  "    if (d->dz[i] < -dz_max && d->lbz[i] - d->z[i] >= d->epr) {\n"
  "      dz_max = -d->dz[i];\n"
  "      d->index = i;\n"
  "      d->sign = -1;\n"
  "      d->msg = \"lbz violated with zero step\";\n"
  "      d->msg_ind = d->index;\n"
  "    } else if (d->dz[i] > dz_max && d->z[i] - d->ubz[i] >= d->epr) {\n"
  "      dz_max = d->dz[i];\n"
  "      d->index = i;\n"
  "      d->sign = 1;\n"
  "      d->msg = \"ubz violated with zero step\";\n"
  "      d->msg_ind = d->index;\n"
  "    }\n"
  "  }\n"
  "  return dz_max > 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_primal_blocking\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_primal_blocking(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i;\n"
  "  T1 trial_z;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Check if violation with tau=0 and not improving\n"
  "  if (casadi_qrqp_zero_blocking(d)) {\n"
  "    d->tau = 0.;\n"
  "    return;\n"
  "  }\n"
  "  // Loop over all primal variables\n"
  "  for (i = 0; i < p->qp->nz; ++i) {\n"
  "    if (d->dz[i] == 0.) continue; // Skip zero steps\n"
  "    // Trial primal step\n"
  "    trial_z = d->z[i] + d->tau * d->dz[i];\n"
  "    if (d->dz[i] < 0 && trial_z < d->lbz[i] - d->epr) {\n"
  "      // Trial would increase maximum infeasibility\n"
  "      d->tau = (d->lbz[i] - d->epr - d->z[i]) / d->dz[i];\n"
  "      d->index = d->lam[i] < 0. ? -1 : i;\n"
  "      d->sign = -1;\n"
  "      d->msg = \"Enforcing lbz\";\n"
  "      d->msg_ind = i;\n"
  "    } else if (d->dz[i] > 0 && trial_z > d->ubz[i] + d->epr) {\n"
  "      // Trial would increase maximum infeasibility\n"
  "      d->tau = (d->ubz[i] + d->epr - d->z[i]) / d->dz[i];\n"
  "      d->index = d->lam[i] > 0. ? -1 : i;\n"
  "      d->sign = 1;\n"
  "      d->msg = \"Enforcing ubz\";\n"
  "      d->msg_ind = i;\n"
  "    }\n"
  "    if (d->tau <= 0) return;\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_dual_breakpoints\"\n"
  "template<typename T1>\n"
  "casadi_int casadi_qrqp_dual_breakpoints(casadi_qrqp_data<T1>* d, T1* tau_list,\n"
  "                                      casadi_int* ind_list, T1 tau) {\n"
  "  // Local variables\n"
  "  casadi_int i, n_tau, loc, next_ind, tmp_ind, j;\n"
  "  T1 trial_lam, new_tau, next_tau, tmp_tau;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Dual feasibility is piecewise linear. Start with one interval [0,tau]:\n"
  "  tau_list[0] = tau;\n"
  "  ind_list[0] = -1; // no associated index\n"
  "  n_tau = 1;\n"
  "  // Find the taus corresponding to lam crossing zero and insert into list\n"
  "  for (i=0; i<p->qp->nz; ++i) {\n"
  "    if (d->dlam[i]==0.) continue; // Skip zero steps\n"
  "    if (d->lam[i]==0.) continue; // Skip inactive constraints\n"
  "    // Trial dual step\n"
  "    trial_lam = d->lam[i] + tau*d->dlam[i];\n"
  "    // Skip if no sign change\n"
  "    if (d->lam[i]>0 ? trial_lam>=0 : trial_lam<=0) continue;\n"
  "    // Location of the sign change\n"
  "    new_tau = -d->lam[i]/d->dlam[i];\n"
  "    // Where to insert the w[i]\n"
  "    for (loc=0; loc<n_tau-1; ++loc) {\n"
  "      if (new_tau<tau_list[loc]) break;\n"
  "    }\n"
  "    // Insert element\n"
  "    n_tau++;\n"
  "    next_tau=new_tau;\n"
  "    next_ind=i;\n"
  "    for (j=loc; j<n_tau; ++j) {\n"
  "      tmp_tau = tau_list[j];\n"
  "      tau_list[j] = next_tau;\n"
  "      next_tau = tmp_tau;\n"
  "      tmp_ind = ind_list[j];\n"
  "      ind_list[j] = next_ind;\n"
  "      next_ind = tmp_ind;\n"
  "    }\n"
  "  }\n"
  "  return n_tau;\n"
  "}\n"
  "// SYMBOL \"qrqp_dual_blocking\"\n"
  "template<typename T1>\n"
  "casadi_int casadi_qrqp_dual_blocking(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i, n_tau, j, k, du_index;\n"
  "  T1 tau_k, dtau, new_infeas, tau1, infeas, tinfeas;\n"
  "  const casadi_int *at_colind, *at_row;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Extract sparsities\n"
  "  at_row = (at_colind = p->sp_at+2) + p->qp->na + 1;\n"
  "  // Dual feasibility is piecewise linear in tau. Get the intervals:\n"
  "  n_tau = casadi_qrqp_dual_breakpoints(d, d->w, d->iw, d->tau);\n"
  "  // No dual blocking yet\n"
  "  du_index = -1;\n"
  "  // How long step can we take without exceeding e?\n"
  "  tau_k = 0.;\n"
  "  for (j=0; j<n_tau; ++j) {\n"
  "    // Distance to the next tau (may be zero)\n"
  "    dtau = d->w[j] - tau_k;\n"
  "    // Check if maximum dual infeasibility gets exceeded\n"
  "    for (k=0; k<p->qp->nx; ++k) {\n"
  "      // Get infeasibility and infeasibility tangent\n"
  "      infeas  = d->infeas[k];\n"
  "      tinfeas  = d->tinfeas[k];\n"
  "      // Make sure tinfeas>0\n"
  "      if (fabs(tinfeas)<1e-14) {\n"
  "        // Skip\n"
  "        continue;\n"
  "      } else if (tinfeas<0) {\n"
  "        // Switch signs\n"
  "        infeas *= -1;\n"
  "        tinfeas *= -1;\n"
  "      }\n"
  "      // Tentative new infeasibility\n"
  "      new_infeas = infeas + dtau*tinfeas;\n"
  "      // Does infeasibility get exceeded\n"
  "      if (new_infeas > d->edu) {\n"
  "        // Sign change and exceeded\n"
  "        tau1 = fmax(tau_k, tau_k + (d->edu - infeas)/tinfeas);\n"
  "        if (tau1 < d->tau) {\n"
  "          // Enforce dual blocking constraint\n"
  "          d->tau = tau1;\n"
  "          du_index = k;\n"
  "        }\n"
  "      }\n"
  "    }\n"
  "    // Update infeasibility\n"
  "    casadi_axpy(p->qp->nx, fmin(d->tau - tau_k, dtau), d->tinfeas, d->infeas);\n"
  "    // Stop here if dual blocking constraint\n"
  "    if (du_index>=0) return du_index;\n"
  "    // Continue to the next tau\n"
  "    tau_k = d->w[j];\n"
  "    // Get component, break if last\n"
  "    i = d->iw[j];\n"
  "    if (i<0) break;\n"
  "    // Update sign or tinfeas\n"
  "    if (!d->neverzero[i]) {\n"
  "      // lam becomes zero, update the infeasibility tangent\n"
  "      if (i<p->qp->nx) {\n"
  "        // Set a lam_x to zero\n"
  "        d->tinfeas[i] -= d->dlam[i];\n"
  "      } else {\n"
  "        // Set a lam_a to zero\n"
  "        for (k=at_colind[i-p->qp->nx]; k<at_colind[i-p->qp->nx+1]; ++k) {\n"
  "          d->tinfeas[at_row[k]] -= d->nz_at[k]*d->dlam[i];\n"
  "        }\n"
  "      }\n"
  "    }\n"
  "  }\n"
  "  return du_index;\n"
  "}\n"
  "// SYMBOL \"qrqp_take_step\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_take_step(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Get current sign\n"
  "  for (i=0; i<p->qp->nz; ++i) d->iw[i] = d->lam[i]>0. ? 1 : d->lam[i]<0 ? -1 : 0;\n"
  "  // Take primal-dual step\n"
  "  casadi_axpy(p->qp->nz, d->tau, d->dz, d->z);\n"
  "  casadi_axpy(p->qp->nz, d->tau, d->dlam, d->lam);\n"
  "  // Update sign\n"
  "  for (i=0; i<p->qp->nz; ++i) {\n"
  "    // Allow sign changes for certain components\n"
  "    if (d->neverzero[i] && (d->iw[i]<0 ? d->lam[i]>0 : d->lam[i]<0)) {\n"
  "      d->iw[i]=-d->iw[i];\n"
  "    }\n"
  "    // Ensure correct sign\n"
  "    switch (d->iw[i]) {\n"
  "      case -1: d->lam[i] = fmin(d->lam[i], -p->dmin); break;\n"
  "      case  1: d->lam[i] = fmax(d->lam[i],  p->dmin); break;\n"
  "      case  0: d->lam[i] = 0.; break;\n"
  "    }\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_flip_check\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_flip_check(casadi_qrqp_data<T1>* d) {\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Calculate the difference between unenforced and enforced column index\n"
  "  casadi_qrqp_kkt_vector(d, d->dlam, d->index);\n"
  "  // Calculate the difference between old and new column index\n"
  "  if (d->sign == 0) casadi_scal(p->qp->nz, -1., d->dlam);\n"
  "  // Try to find a linear combination of the new columns\n"
  "  casadi_qr_solve(d->dlam, 1, 0, p->sp_v, d->nz_v, p->sp_r, d->nz_r, d->beta,\n"
  "    p->prinv, p->pc, d->w);\n"
  "  // If dlam[index]!=1, new columns must be linearly independent\n"
  "  if (fabs(d->dlam[d->index]-1.) >= 1e-12) return 0;\n"
  "  // Next, find a linear combination of the new rows\n"
  "  casadi_clear(d->dz, p->qp->nz);\n"
  "  d->dz[d->index] = 1;\n"
  "  casadi_qr_solve(d->dz, 1, 1, p->sp_v, d->nz_v, p->sp_r, d->nz_r, d->beta,\n"
  "    p->prinv, p->pc, d->w);\n"
  "  // Normalize dlam, dz\n"
  "  casadi_scal(p->qp->nz, 1./sqrt(casadi_dot(p->qp->nz, d->dlam, d->dlam)), d->dlam);\n"
  "  casadi_scal(p->qp->nz, 1./sqrt(casadi_dot(p->qp->nz, d->dz, d->dz)), d->dz);\n"
  "  // KKT system will be singular\n"
  "  return 1;\n"
  "}\n"
  "// SYMBOL \"qrqp_factorize\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_factorize(casadi_qrqp_data<T1>* d) {\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Do we already have a search direction due to lost singularity?\n"
  "  if (d->has_search_dir) {\n"
  "    d->sing = 1;\n"
  "    return;\n"
  "  }\n"
  "  // Construct the KKT matrix\n"
  "  casadi_qrqp_kkt(d);\n"
  "  // QR factorization\n"
  "  casadi_qr(p->sp_kkt, d->nz_kkt, d->w, p->sp_v, d->nz_v, p->sp_r,\n"
  "            d->nz_r, d->beta, p->prinv, p->pc);\n"
  "  // Check singularity\n"
  "  d->sing = casadi_qr_singular(&d->mina, &d->imina, d->nz_r, p->sp_r, p->pc, 1e-12);\n"
  "}\n"
  "// SYMBOL \"qrqp_expand_step\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_expand_step(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Calculate change in Lagrangian gradient\n"
  "  casadi_clear(d->dlam, p->qp->nx);\n"
  "  casadi_mv(d->qp->h, p->qp->sp_h, d->dz, d->dlam, 0); // gradient of the objective\n"
  "  casadi_mv(d->qp->a, p->qp->sp_a, d->dz + p->qp->nx, d->dlam, 1); // gradient of the Lagrangian\n"
  "  // Step in lam[:nx]\n"
  "  casadi_scal(p->qp->nx, -1., d->dlam);\n"
  "  // For inactive constraints, lam(x) step is zero\n"
  "  for (i = 0; i < p->qp->nx; ++i) if (d->lam[i] == 0.) d->dlam[i] = 0.;\n"
  "  // Step in lam[nx:]\n"
  "  casadi_copy(d->dz+p->qp->nx, p->qp->na, d->dlam + p->qp->nx);\n"
  "  // Step in z[nx:]\n"
  "  casadi_clear(d->dz + p->qp->nx, p->qp->na);\n"
  "  casadi_mv(d->qp->a, p->qp->sp_a, d->dz, d->dz + p->qp->nx, 0);\n"
  "  // Avoid steps that are nonzero due to numerics\n"
  "  for (i = 0; i < p->qp->nz; ++i) if (fabs(d->dz[i]) < 1e-14) d->dz[i] = 0.;\n"
  "  // Tangent of the dual infeasibility at tau=0\n"
  "  casadi_clear(d->tinfeas, p->qp->nx);\n"
  "  casadi_mv(d->qp->h, p->qp->sp_h, d->dz, d->tinfeas, 0);\n"
  "  casadi_mv(d->qp->a, p->qp->sp_a, d->dlam + p->qp->nx, d->tinfeas, 1);\n"
  "  casadi_axpy(p->qp->nx, 1., d->dlam, d->tinfeas);\n"
  "}\n"
  "// SYMBOL \"casadi_qrqp_pr_direction\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_pr_direction(casadi_qrqp_data<T1>* d) {\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  for (i=0; i<p->qp->nz; ++i) {\n"
  "    if (d->lbz[i] - d->z[i] >= d->epr) {\n"
  "      // Prevent further violation of lower bound\n"
  "      if (d->dz[i] < 0 || d->dlam[i] > 0) return 1;\n"
  "    } else if (d->z[i] - d->ubz[i] >= d->epr) {\n"
  "      // Prevent further violation of upper bound\n"
  "      if (d->dz[i] > 0 || d->dlam[i] < 0) return 1;\n"
  "    }\n"
  "  }\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"casadi_qrqp_du_direction\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_du_direction(casadi_qrqp_data<T1>* d) {\n"
  "  casadi_int i;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  for (i=0; i<p->qp->nx; ++i) {\n"
  "    // Prevent further increase in dual infeasibility\n"
  "    if (d->infeas[i] <= -d->edu && d->tinfeas[i] < -1e-12) {\n"
  "      return 1;\n"
  "    } else if (d->infeas[i] >= d->edu && d->tinfeas[i] > 1e-12) {\n"
  "      return 1;\n"
  "    }\n"
  "  }\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_enforceable\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_enforceable(casadi_qrqp_data<T1>* d, casadi_int i, casadi_int s) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  const casadi_int *at_colind, *at_row;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Can always enforce if not at bound\n"
  "  if (fabs(d->infeas[i]) < d->edu) return 1;\n"
  "  // AT sparsity\n"
  "  at_colind = p->sp_at + 2;\n"
  "  at_row = at_colind + p->qp->na + 1;\n"
  "  // Can we set lam[i] := s*DMIN without exceeding edu?\n"
  "  if (i<p->qp->nx) {\n"
  "    return (s < 0) == (d->infeas[i] > 0);\n"
  "  } else {\n"
  "    for (k=at_colind[i-p->qp->nx]; k<at_colind[i-p->qp->nx+1]; ++k) {\n"
  "      if (d->nz_at[k] > 0) {\n"
  "        if ((s > 0) == (d->infeas[at_row[k]] > 0)) return 0;\n"
  "      } else if (d->nz_at[k] < 0) {\n"
  "        if ((s < 0) == (d->infeas[at_row[k]] > 0)) return 0;\n"
  "      }\n"
  "    }\n"
  "    return 1;\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_singular_step\"\n"
  "// C-REPLACE \"static_cast<T1*>(0)\" \"0\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_singular_step(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  T1 tau_test, tau;\n"
  "  casadi_int nnz_kkt, nk, k, i, best_k, best_neg, neg;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Find the columns that take part in any linear combination\n"
  "  for (i = 0; i < p->qp->nz; ++i) d->lincomb[i] = 0;\n"
  "  for (k = 0; k < d->sing; ++k) {\n"
  "    if (!d->has_search_dir) {\n"
  "      casadi_qr_colcomb(d->dlam, d->nz_r, p->sp_r, p->pc, 1e-12, k);\n"
  "    }\n"
  "    for (i = 0; i < p->qp->nz; ++i) if (fabs(d->dlam[i]) >= 1e-12) d->lincomb[i]++;\n"
  "  }\n"
  "  if (d->has_search_dir) {\n"
  "    // One, given search direction\n"
  "    nk = 1;\n"
  "  } else {\n"
  "    // QR factorization of the transpose\n"
  "    casadi_trans(d->nz_kkt, p->sp_kkt, d->nz_v, p->sp_kkt, d->iw);\n"
  "    nnz_kkt = p->sp_kkt[2+p->qp->nz]; // kkt_colind[nz]\n"
  "    casadi_copy(d->nz_v, nnz_kkt, d->nz_kkt);\n"
  "    casadi_qr(p->sp_kkt, d->nz_kkt, d->w, p->sp_v, d->nz_v, p->sp_r, d->nz_r,\n"
  "              d->beta, p->prinv, p->pc);\n"
  "    // For all nullspace vectors\n"
  "    nk = casadi_qr_singular(static_cast<T1*>(0), 0, d->nz_r, p->sp_r, p->pc, 1e-12);\n"
  "  }\n"
  "  // Best flip\n"
  "  best_k = best_neg = -1;\n"
  "  tau = p->inf;\n"
  "  for (k=0; k<nk; ++k) {\n"
  "    if (!d->has_search_dir) {\n"
  "      // Get a linear combination of the rows in kkt\n"
  "      casadi_qr_colcomb(d->dz, d->nz_r, p->sp_r, p->pc, 1e-12, k);\n"
  "    }\n"
  "    // Which constraints can be flipped in order to increase rank?\n"
  "    for (i=0; i<p->qp->nz; ++i) {\n"
  "      d->iw[i] = d->lincomb[i] && fabs(casadi_qrqp_kkt_dot(d, d->dz, i)) > 1e-12;\n"
  "    }\n"
  "    // Calculate step, dz and dlam\n"
  "    casadi_qrqp_expand_step(d);\n"
  "    // Try both positive and negative direction\n"
  "    for (neg = 0; neg < 2; ++neg) {\n"
  "      // Negate direction\n"
  "      if (neg) {\n"
  "        casadi_scal(p->qp->nz, -1., d->dz);\n"
  "        casadi_scal(p->qp->nz, -1., d->dlam);\n"
  "        casadi_scal(p->qp->nx, -1., d->tinfeas);\n"
  "      }\n"
  "      // Make sure primal infeasibility doesn't exceed limits\n"
  "      if (casadi_qrqp_pr_direction(d)) continue;\n"
  "      // Make sure dual infeasibility doesn't exceed limits\n"
  "      if (casadi_qrqp_du_direction(d)) continue;\n"
  "      // Loop over potential active set changes\n"
  "      for (i=0; i<p->qp->nz; ++i) {\n"
  "        // Skip if no rank increase\n"
  "        if (!d->iw[i]) continue;\n"
  "        // Enforced or not?\n"
  "        if (d->lam[i]==0.) {\n"
  "          if (d->z[i] <= d->ubz[i] && (d->z[i] >= d->lbz[i] ?\n"
  "              d->dz[i] < -1e-12 : d->dz[i] > 1e-12)) {\n"
  "            // Enforce lower bound?\n"
  "            if (!d->neverlower[i]\n"
  "                && (tau_test = (d->lbz[i] - d->z[i]) / d->dz[i]) < tau\n"
  "                && casadi_qrqp_enforceable(d, i, -1)) {\n"
  "              tau = tau_test;\n"
  "              d->r_index = i;\n"
  "              d->r_sign = -1;\n"
  "              best_k = k;\n"
  "              best_neg = neg;\n"
  "            }\n"
  "          } else if (d->z[i] >= d->lbz[i] && (d->z[i] <= d->ubz[i] ?\n"
  "              d->dz[i] > 1e-12 : d->dz[i] < -1e-12)) {\n"
  "            // Enforce upper bound?\n"
  "            if (!d->neverupper[i]\n"
  "                && (tau_test = (d->ubz[i] - d->z[i]) / d->dz[i]) < tau\n"
  "                && casadi_qrqp_enforceable(d, i, 1)) {\n"
  "              tau = tau_test;\n"
  "              d->r_index = i;\n"
  "              d->r_sign = 1;\n"
  "              best_k = k;\n"
  "              best_neg = neg;\n"
  "            }\n"
  "          }\n"
  "        } else if (!d->neverzero[i]) {\n"
  "          // Drop a constraint?\n"
  "          if (d->lam[i] > 0 ? d->dlam[i] < -1e-12 : d->dlam[i] > 1e-12) {\n"
  "            if ((tau_test = -d->lam[i] / d->dlam[i]) < tau) {\n"
  "              tau = tau_test;\n"
  "              d->r_index = i;\n"
  "              d->r_sign = 0;\n"
  "              best_k = k;\n"
  "              best_neg = neg;\n"
  "            }\n"
  "          }\n"
  "        }\n"
  "      }\n"
  "    }\n"
  "  }\n"
  "  // Can we restore feasibility?\n"
  "  if (d->r_index < 0) return 1;\n"
  "  // Recalculate direction, if needed\n"
  "  if (--k != best_k) {\n"
  "    // Need to recalculate direction\n"
  "    casadi_qr_colcomb(d->dz, d->nz_r, p->sp_r, p->pc, 1e-12, best_k);\n"
  "    casadi_qrqp_expand_step(d);\n"
  "    if (best_neg) tau *= -1;\n"
  "  } else if (--neg != best_neg) {\n"
  "    // No need to recalculate, but opposite direction\n"
  "    tau *= -1;\n"
  "  }\n"
  "  // Scale step so that that tau=1 corresponds to a full step\n"
  "  casadi_scal(p->qp->nz, tau, d->dz);\n"
  "  casadi_scal(p->qp->nz, tau, d->dlam);\n"
  "  casadi_scal(p->qp->nx, tau, d->tinfeas);\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_calc_step\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_calc_step(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Reset returns\n"
  "  d->r_index = -1;\n"
  "  d->r_sign = 0;\n"
  "  // Handle singularity\n"
  "  if (d->sing) return casadi_qrqp_singular_step(d);\n"
  "  // Negative KKT residual\n"
  "  casadi_qrqp_kkt_residual(d, d->dz);\n"
  "  // Solve to get step in z[:nx] and lam[nx:]\n"
  "  casadi_qr_solve(d->dz, 1, 1, p->sp_v, d->nz_v, p->sp_r, d->nz_r, d->beta,\n"
  "                  p->prinv, p->pc, d->w);\n"
  "  // Have step in dz[:nx] and dlam[nx:]. Calculate complete dz and dlam\n"
  "  casadi_qrqp_expand_step(d);\n"
  "  // Successful return\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_calc_sens\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_calc_sens(casadi_qrqp_data<T1>* d, casadi_int i) {\n"
  "  // Local variables\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Calculate sensitivities in decreasing dual infeasibility index i\n"
  "  casadi_clear(d->sens, p->qp->nz);\n"
  "  if (i >= 0) {\n"
  "    d->sens[i] = d->infeas[i] > 0 ? -1. : 1.;\n"
  "    casadi_mv(d->qp->a, p->qp->sp_a, d->sens, d->sens + p->qp->nx, 0);\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_calc_dependent\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_calc_dependent(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int i;\n"
  "  T1 r;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Calculate f\n"
  "  d->f = casadi_bilin(d->qp->h, p->qp->sp_h, d->z, d->z)/2.\n"
  "       + casadi_dot(p->qp->nx, d->z, d->qp->g);\n"
  "  // Calculate z[nx:]\n"
  "  casadi_clear(d->z+p->qp->nx, p->qp->na);\n"
  "  casadi_mv(d->qp->a, p->qp->sp_a, d->z, d->z+p->qp->nx, 0);\n"
  "  // Calculate gradient of the Lagrangian\n"
  "  casadi_copy(d->qp->g, p->qp->nx, d->infeas);\n"
  "  casadi_mv(d->qp->h, p->qp->sp_h, d->z, d->infeas, 0);\n"
  "  casadi_mv(d->qp->a, p->qp->sp_a, d->lam+p->qp->nx, d->infeas, 1);\n"
  "  // Calculate lam[:nx] without changing the sign accidentally, dual infeasibility\n"
  "  for (i=0; i<p->qp->nx; ++i) {\n"
  "    // No change if zero\n"
  "    if (d->lam[i]==0) continue;\n"
  "    // lam[i] with no sign restrictions\n"
  "    r = -d->infeas[i];\n"
  "    if (d->lam[i]>0) {\n"
  "      if (d->neverzero[i] && !d->neverlower[i]) {\n"
  "        d->lam[i] = r==0 ? p->dmin : r; // keep sign if r==0\n"
  "      } else {\n"
  "        d->lam[i] = fmax(r, p->dmin); // no sign change\n"
  "      }\n"
  "    } else {\n"
  "      if (d->neverzero[i] && !d->neverupper[i]) {\n"
  "        d->lam[i] = r==0 ? -p->dmin : r; // keep sign if r==0\n"
  "      } else {\n"
  "        d->lam[i] = fmin(r, -p->dmin); // no sign change\n"
  "      }\n"
  "    }\n"
  "    // Update dual infeasibility\n"
  "    d->infeas[i] += d->lam[i];\n"
  "  }\n"
  "  // Calculate primal and dual error\n"
  "  casadi_qrqp_pr(d);\n"
  "  casadi_qrqp_du(d);\n"
  "  // Acceptable primal and dual error\n"
  "  d->epr = fmax(d->pr, (0.5 * p->constr_viol_tol / p->dual_inf_tol) * d->du);\n"
  "  d->edu = fmax(d->du, (0.5 * p->dual_inf_tol / p->constr_viol_tol) * d->pr);\n"
  "  // Sensitivity in decreasing |du|\n"
  "  casadi_qrqp_calc_sens(d, d->idu);\n"
  "}\n"
  "// SYMBOL \"qrqp_linesearch\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_linesearch(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int du_index;\n"
  "  // Start with a full step and no active set change\n"
  "  d->sign = 0;\n"
  "  d->index = -1;\n"
  "  d->tau = 1.;\n"
  "  // Find largest possible step without exceeding acceptable |pr|\n"
  "  casadi_qrqp_primal_blocking(d);\n"
  "  // Find largest possible step without exceeding acceptable |du|\n"
  "  du_index = casadi_qrqp_dual_blocking(d);\n"
  "  // Take primal-dual step, avoiding accidental sign changes for lam\n"
  "  casadi_qrqp_take_step(d);\n"
  "  // Handle dual blocking constraints\n"
  "  if (du_index >= 0) {\n"
  "    // Sensititivity in decreasing du_index\n"
  "    casadi_qrqp_calc_sens(d, du_index);\n"
  "    // Find corresponding index\n"
  "    casadi_qrqp_du_index(d);\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_flip\"\n"
  "template<typename T1>\n"
  "void casadi_qrqp_flip(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Try to restore regularity if possible\n"
  "  if (d->index == -1 && d->r_index >= 0) {\n"
  "    if (d->r_sign != 0 || casadi_qrqp_du_check(d, d->r_index)) {\n"
  "      d->index = d->r_index;\n"
  "      d->sign = d->r_sign;\n"
  "      if (d->sign > 0) {\n"
  "        d->msg = \"Enforced ubz for regularity\";\n"
  "      } else if (d->sign < 0) {\n"
  "        d->msg = \"Enforced lbz for regularity\";\n"
  "      } else if (d->lam[d->index] > 0) {\n"
  "        d->msg = \"Dropped ubz for regularity\";\n"
  "      } else {\n"
  "        d->msg = \"Dropped lbz for regularity\";\n"
  "      }\n"
  "      d->msg_ind = d->index;\n"
  "    }\n"
  "  }\n"
  "  // If nonsingular and nonzero error, try to flip a constraint\n"
  "  if (!d->sing && d->index == -1) {\n"
  "    if (d->pr * p->dual_inf_tol >= p->constr_viol_tol * d->du) {\n"
  "      // Improve primal feasibility if dominating\n"
  "      if (d->pr >= p->constr_viol_tol) casadi_qrqp_pr_index(d);\n"
  "    } else {\n"
  "      // Improve dual feasibility if dominating\n"
  "      if (d->du >= p->dual_inf_tol) casadi_qrqp_du_index(d);\n"
  "    }\n"
  "  }\n"
  "  // No search direction given by default\n"
  "  d->has_search_dir = 0;\n"
  "  // If a constraint was added\n"
  "  if (d->index >= 0) {\n"
  "    // Detect singularity before it happens and get nullspace vectors\n"
  "    if (!d->sing) d->has_search_dir = casadi_qrqp_flip_check(d);\n"
  "    // Perform the active-set change\n"
  "    d->lam[d->index] = d->sign==0 ? 0 : d->sign > 0 ? p->dmin : -p->dmin;\n"
  "    // Recalculate primal and dual infeasibility\n"
  "    casadi_qrqp_calc_dependent(d);\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_prepare\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_prepare(casadi_qrqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  // Calculate dependent quantities\n"
  "  casadi_qrqp_calc_dependent(d);\n"
  "  // Make an active set change\n"
  "  casadi_qrqp_flip(d);\n"
  "  // Form and factorize the KKT system\n"
  "  casadi_qrqp_factorize(d);\n"
  "  // Termination message\n"
  "  if (!d->sing && d->index == -1) {\n"
  "    d->status = QP_SUCCESS;\n"
  "    d->msg = \"Converged\";\n"
  "    d->msg_ind = -2;\n"
  "    return 1;\n"
  "  } else if (d->iter >= p->max_iter) {\n"
  "    d->status = QP_MAX_ITER;\n"
  "    d->msg = \"Max iter\";\n"
  "    d->msg_ind = -2;\n"
  "    return 1;\n"
  "  } else if (!d->sing && d->ipr < 0 && d->idu < 0) {\n"
  "    d->status = QP_SUCCESS;\n"
  "    d->msg = \"No primal or dual error\";\n"
  "    d->msg_ind = -2;\n"
  "    return 1;\n"
  "  } else {\n"
  "    // Keep iterating\n"
  "    return 0;\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"qrqp_iterate\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_iterate(casadi_qrqp_data<T1>* d) {\n"
  "  // Reset message flag\n"
  "  d->msg = 0;\n"
  "  // Start a new iteration\n"
  "  d->iter++;\n"
  "  // Calculate search direction\n"
  "  if (casadi_qrqp_calc_step(d)) {\n"
  "    d->status = QP_NO_SEARCH_DIR;\n"
  "    return 1;\n"
  "  }\n"
  "  // Line search in the calculated direction\n"
  "  casadi_qrqp_linesearch(d);\n"
  "  // Keep iterating\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_print_header\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_print_header(casadi_qrqp_data<T1>* d, char* buf, size_t buf_sz) {\n"
  "#ifdef CASADI_SNPRINTF\n"
  "  int flag;\n"
  "  // Print to string\n"
  "  flag = CASADI_SNPRINTF(buf, buf_sz, \"%5s %5s %9s %9s %5s %9s %5s %9s %5s %9s  %4s\",\n"
  "          \"Iter\", \"Sing\", \"fk\", \"|pr|\", \"con\", \"|du|\", \"var\",\n"
  "          \"min_R\", \"con\", \"last_tau\", \"Note\");\n"
  "  // Check if error\n"
  "  if (flag < 0) {\n"
  "    d->status = QP_PRINTING_ERROR;\n"
  "    return 1;\n"
  "  }\n"
  "#else\n"
  "  if (buf_sz) buf[0] = '\\0';\n"
  "#endif\n"
  "  // Successful return\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_print_colcomb\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_print_colcomb(casadi_qrqp_data<T1>* d, char* buf, size_t buf_sz, casadi_int j) {\n"
  "#ifdef CASADI_SNPRINTF\n"
  "  casadi_int num_size, n_print, i, k, buf_offset, val;\n"
  "  size_t b;\n"
  "  const casadi_qrqp_prob<T1>* p = d->prob;\n"
  "  casadi_qr_colcomb(d->dlam, d->nz_r, p->sp_r, p->pc, 1e-12, j);\n"
  "  // Determine max printing size\n"
  "  num_size = 1;\n"
  "  val = p->qp->nz-1;\n"
  "  while (val) {\n"
  "    val/=10;\n"
  "    num_size++;\n"
  "  }\n"
  "  if (buf_sz<=4) return 1;\n"
  "  // How many numbers can be printed?\n"
  "  // Need some extra space for '...'\n"
  "  // and null\n"
  "  n_print = (buf_sz-4)/num_size;\n"
  "  // Clear buffer\n"
  "  for (b=0;b<buf_sz;++b) buf[b]=' ';\n"
  "  buf_offset = 0;\n"
  "  for (i=0;i<p->qp->nz;++i) {\n"
  "    if (fabs(d->dlam[i]) >= 1e-12) {\n"
  "      if (n_print==0) {\n"
  "        buf[buf_sz-4] = '.';\n"
  "        buf[buf_sz-3] = '.';\n"
  "        buf[buf_sz-2] = '.';\n"
  "        buf[buf_sz-1] = '\\0';\n"
  "        return 1;\n"
  "      }\n"
  "      n_print--;\n"
  "      CASADI_SNPRINTF(buf+buf_offset, num_size, \"%d\", static_cast<int>(i));\n"
  "      // Clear null chars\n"
  "      for (k=0;k<num_size;++k) {\n"
  "        if (buf[buf_offset+k]=='\\0') buf[buf_offset+k] = ' ';\n"
  "      }\n"
  "      buf_offset += num_size;\n"
  "    }\n"
  "  }\n"
  "  buf[buf_sz-1] = '\\0';\n"
  "#else\n"
  "  if (buf_sz) buf[0] = '\\0';\n"
  "#endif\n"
  "  // Successful return\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"qrqp_print_iteration\"\n"
  "template<typename T1>\n"
  "int casadi_qrqp_print_iteration(casadi_qrqp_data<T1>* d, char* buf, int buf_sz) {\n"
  "#ifdef CASADI_SNPRINTF\n"
  "  int flag;\n"
  "  // Print iteration data without note to string\n"
  "  flag = CASADI_SNPRINTF(buf, buf_sz,\n"
  "    \"%5d %5d %9.2g %9.2g %5d %9.2g %5d %9.2g %5d %9.2g  \",\n"
  "    static_cast<int>(d->iter), static_cast<int>(d->sing), d->f, d->pr,\n"
  "    static_cast<int>(d->ipr), d->du, static_cast<int>(d->idu),\n"
  "    d->mina, static_cast<int>(d->imina), d->tau);\n"
  "  // Check if error\n"
  "  if (flag < 0) {\n"
  "    d->status = QP_PRINTING_ERROR;\n"
  "    return 1;\n"
  "  }\n"
  "  // Rest of buffer reserved for iteration note\n"
  "  buf += flag;\n"
  "  buf_sz -= flag;\n"
  "  // Print iteration note, if any\n"
  "  if (d->msg) {\n"
  "    if (d->msg_ind > -2) {\n"
  "      flag = CASADI_SNPRINTF(buf, buf_sz, \"%s, i=%d\", d->msg, static_cast<int>(d->msg_ind));\n"
  "    } else {\n"
  "      flag = CASADI_SNPRINTF(buf, buf_sz, \"%s\", d->msg);\n"
  "    }\n"
  "    // Check if error\n"
  "    if (flag < 0) {\n"
  "      d->status = QP_PRINTING_ERROR;\n"
  "      return 1;\n"
  "    }\n"
  "  }\n"
  "#else\n"
  "  if (buf_sz) buf[0] = '\\0';\n"
  "#endif\n"
  "  // Successful return\n"
  "  return 0;\n"
  "}\n";

const char* casadi_kkt_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"kkt\"\n"
  "template<typename T1>\n"
  "void casadi_kkt(const casadi_int* sp_kkt, T1* nz_kkt,\n"
  "    const casadi_int* sp_h, const T1* nz_h,\n"
  "    const casadi_int* sp_a, const T1* nz_a,\n"
  "    const T1* S, const T1* D, T1* w, casadi_int* iw) {\n"
  "  // Local variables\n"
  "  casadi_int i, k, j, nx, nz;\n"
  "  const casadi_int *h_colind, *h_row, *a_colind, *a_row,\n"
  "                   *kkt_colind, *kkt_row;\n"
  "  // Extract sparsities\n"
  "  a_row = (a_colind = sp_a + 2) + (nx = sp_a[1]) + 1;\n"
  "  h_row = (h_colind = sp_h + 2) + nx + 1;\n"
  "  kkt_row = (kkt_colind = sp_kkt + 2) + (nz = sp_kkt[1]) + 1;\n"
  "  // Running indices for each row of A\n"
  "  for (i = nx; i < nz; ++i) iw[i - nx] = kkt_colind[i];\n"
  "  // Reset w to zero\n"
  "  casadi_clear(w, nz);\n"
  "  // Loop over columns of [H + D_x; A]\n"
  "  for (i=0; i<nx; ++i) {\n"
  "    // Copy scaled column of H to w\n"
  "    for (k=h_colind[i]; k<h_colind[i+1]; ++k) {\n"
  "      j = h_row[k];\n"
  "      w[j] = nz_h[k] * S[i] * S[j];\n"
  "    }\n"
  "    // Copy scaled column of A to w\n"
  "    for (k=a_colind[i]; k<a_colind[i+1]; ++k) {\n"
  "      j = a_row[k] + nx;\n"
  "      w[j] = nz_a[k] * S[i] * S[j];\n"
  "    }\n"
  "    // Add D_x to diagonal\n"
  "    w[i] += D[i];\n"
  "    // Copy column to KKT\n"
  "    for (k=kkt_colind[i]; k<kkt_colind[i+1]; ++k) {\n"
  "      j = kkt_row[k];\n"
  "      nz_kkt[k] = w[j];\n"
  "      if (j >= nx) nz_kkt[iw[j - nx]++] = w[j];\n"
  "    }\n"
  "    // Zero out w\n"
  "    for (k=h_colind[i]; k<h_colind[i+1]; ++k) w[h_row[k]] = 0;\n"
  "    for (k=a_colind[i]; k<a_colind[i+1]; ++k) w[a_row[k] + nx] = 0;\n"
  "  }\n"
  "  // Copy -D_g to diagonal\n"
  "  for (i=nx; i<nz; ++i) {\n"
  "    nz_kkt[iw[i - nx]++] = -D[i];\n"
  "  }\n"
  "}\n";

const char* casadi_ipqp_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// C-REPLACE \"fmin\" \"casadi_fmin\"\n"
  "// C-REPLACE \"fmax\" \"casadi_fmax\"\n"
  "// C-REPLACE \"std::numeric_limits<T1>::min()\" \"casadi_real_min\"\n"
  "// C-REPLACE \"std::numeric_limits<T1>::infinity()\" \"casadi_inf\"\n"
  "// C-REPLACE \"static_cast<int>\" \"(int) \"\n"
  "// SYMBOL \"ipqp_prob\"\n"
  "template<typename T1>\n"
  "struct casadi_ipqp_prob {\n"
  "  // Dimensions\n"
  "  casadi_int nx, na, nz;\n"
  "  // Smallest nonzero number\n"
  "  T1 dmin;\n"
  "  // Infinity\n"
  "  T1 inf;\n"
  "  // Maximum number of iterations\n"
  "  casadi_int max_iter;\n"
  "  // Error tolerance\n"
  "  T1 pr_tol, du_tol, co_tol, mu_tol;\n"
  "};\n"
  "// C-REPLACE \"casadi_ipqp_prob<T1>\" \"struct casadi_ipqp_prob\"\n"
  "// SYMBOL \"ipqp_setup\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_setup(casadi_ipqp_prob<T1>* p, casadi_int nx, casadi_int na) {\n"
  "  p->nx = nx;\n"
  "  p->na = na;\n"
  "  p->nz = nx + na;\n"
  "  p->dmin = std::numeric_limits<T1>::min();\n"
  "  p->inf = std::numeric_limits<T1>::infinity();\n"
  "  p->max_iter = 100;\n"
  "  p->pr_tol = 1e-8;\n"
  "  p->du_tol = 1e-8;\n"
  "  p->co_tol = 1e-8;\n"
  "  p->mu_tol = 1e-8;\n"
  "}\n"
  "// SYMBOL \"ipqp_flag_t\"\n"
  "typedef enum {\n"
  "  IPQP_SUCCESS,\n"
  "  IPQP_MAX_ITER,\n"
  "  IPQP_NO_SEARCH_DIR,\n"
  "  IPQP_MV_ERROR,\n"
  "  IPQP_FACTOR_ERROR,\n"
  "  IPQP_SOLVE_ERROR,\n"
  "  IPQP_PROGRESS_ERROR\n"
  "} casadi_ipqp_flag_t;\n"
  "// SYMBOL \"ipqp_task_t\"\n"
  "typedef enum {\n"
  "  IPQP_MV,\n"
  "  IPQP_PROGRESS,\n"
  "  IPQP_FACTOR,\n"
  "  IPQP_SOLVE} casadi_ipqp_task_t;\n"
  "// SYMBOL \"ipqp_task_t\"\n"
  "typedef enum {\n"
  "  IPQP_RESET,\n"
  "  IPQP_RESIDUAL,\n"
  "  IPQP_NEWITER,\n"
  "  IPQP_PREPARE,\n"
  "  IPQP_PREDICTOR,\n"
  "  IPQP_CORRECTOR} casadi_ipqp_next_t;\n"
  "// SYMBOL \"ipqp_blocker_t\"\n"
  "typedef enum {\n"
  "  IPQP_NONE = 0x0,\n"
  "  IPQP_UPPER = 0x1,\n"
  "  IPQP_LOWER = 0x2,\n"
  "  IPQP_PRIMAL = 0x4,\n"
  "  IPQP_DUAL = 0x8\n"
  "} casadi_blocker_t;\n"
  "// SYMBOL \"ipqp_data\"\n"
  "template<typename T1>\n"
  "struct casadi_ipqp_data {\n"
  "  // Problem structure\n"
  "  const casadi_ipqp_prob<T1>* prob;\n"
  "  // QP data\n"
  "  const T1 *g;\n"
  "  // Number of finite constraints\n"
  "  casadi_int n_con;\n"
  "  // Solver status\n"
  "  casadi_ipqp_flag_t status;\n"
  "  // User task\n"
  "  casadi_ipqp_task_t task;\n"
  "  // Next step\n"
  "  casadi_ipqp_next_t next;\n"
  "  // Linear system\n"
  "  T1* linsys;\n"
  "  // Message buffer\n"
  "  const char *msg;\n"
  "  // Complementarity measure\n"
  "  T1 mu;\n"
  "  // Stepsize\n"
  "  T1 tau;\n"
  "  // Primal and dual error, complementarity error, corresponding index\n"
  "  T1 pr, du, co;\n"
  "  casadi_int ipr, idu, ico;\n"
  "  // Iteration\n"
  "  casadi_int iter;\n"
  "  // Bounds\n"
  "  T1 *lbz, *ubz;\n"
  "  // Current solution\n"
  "  T1 *z, *lam, *lam_lbz, *lam_ubz;\n"
  "  // Step\n"
  "  T1 *dz, *dlam, *dlam_lbz, *dlam_ubz;\n"
  "  // Residual\n"
  "  T1 *rz, *rlam, *rlam_lbz, *rlam_ubz;\n"
  "  // Diagonal entries\n"
  "  T1* D;\n"
  "  // Scaling factor\n"
  "  T1* S;\n"
  "  // Inverse of margin to bounds (0 if no bound)\n"
  "  T1 *dinv_lbz, *dinv_ubz;\n"
  "};\n"
  "// C-REPLACE \"casadi_ipqp_data<T1>\" \"struct casadi_ipqp_data\"\n"
  "// SYMBOL \"ipqp_sz_w\"\n"
  "template<typename T1>\n"
  "casadi_int casadi_ipqp_sz_w(const casadi_ipqp_prob<T1>* p) {\n"
  "  // Return value\n"
  "  casadi_int sz_w = 0;\n"
  "  // Persistent work vectors\n"
  "  sz_w += p->nz; // lbz\n"
  "  sz_w += p->nz; // ubz\n"
  "  sz_w += p->nz; // z\n"
  "  sz_w += p->nz; // lam\n"
  "  sz_w += p->nz; // lam_lbz\n"
  "  sz_w += p->nz; // lam_ubz\n"
  "  sz_w += p->nz; // dz\n"
  "  sz_w += p->nz; // dlam\n"
  "  sz_w += p->nz; // dlam_lbz\n"
  "  sz_w += p->nz; // dlam_ubz\n"
  "  sz_w += p->nz; // rz\n"
  "  sz_w += p->nz; // rlam\n"
  "  sz_w += p->nz; // rlam_lbz\n"
  "  sz_w += p->nz; // rlam_ubz\n"
  "  sz_w += p->nz; // D\n"
  "  sz_w += p->nz; // S\n"
  "  sz_w += p->nz; // dinv_lbz\n"
  "  sz_w += p->nz; // dinv_ubz\n"
  "  return sz_w;\n"
  "}\n"
  "// SYMBOL \"ipqp_init\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_init(casadi_ipqp_data<T1>* d, casadi_int** iw, T1** w) {\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Assign memory\n"
  "  d->lbz = *w; *w += p->nz;\n"
  "  d->ubz = *w; *w += p->nz;\n"
  "  d->z = *w; *w += p->nz;\n"
  "  d->lam = *w; *w += p->nz;\n"
  "  d->lam_lbz = *w; *w += p->nz;\n"
  "  d->lam_ubz = *w; *w += p->nz;\n"
  "  d->dz = *w; *w += p->nz;\n"
  "  d->dlam = *w; *w += p->nz;\n"
  "  d->dlam_lbz = *w; *w += p->nz;\n"
  "  d->dlam_ubz = *w; *w += p->nz;\n"
  "  d->rz = *w; *w += p->nz;\n"
  "  d->rlam = *w; *w += p->nz;\n"
  "  d->rlam_lbz = *w; *w += p->nz;\n"
  "  d->rlam_ubz = *w; *w += p->nz;\n"
  "  d->D = *w; *w += p->nz;\n"
  "  d->S = *w; *w += p->nz;\n"
  "  d->dinv_lbz = *w; *w += p->nz;\n"
  "  d->dinv_ubz = *w; *w += p->nz;\n"
  "  // New QP\n"
  "  d->next = IPQP_RESET;\n"
  "}\n"
  "// SYMBOL \"ipqp_bounds\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_bounds(casadi_ipqp_data<T1>* d, const T1* g,\n"
  "    const T1* lbx, const T1* ubx, const T1* lba, const T1* uba) {\n"
  "  // Local variables\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Pass pointer to linear term in objective\n"
  "  d->g = g;\n"
  "  // Pass bounds on z\n"
  "  casadi_copy(lbx, p->nx, d->lbz);\n"
  "  casadi_copy(lba, p->na, d->lbz + p->nx);\n"
  "  casadi_copy(ubx, p->nx, d->ubz);\n"
  "  casadi_copy(uba, p->na, d->ubz + p->nx);\n"
  "}\n"
  "// SYMBOL \"ipqp_guess\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_guess(casadi_ipqp_data<T1>* d,\n"
  "    const T1* x0, const T1* lam_x0, const T1* lam_a0) {\n"
  "  // Local variables\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Pass initial guess\n"
  "  casadi_copy(x0, p->nx, d->z);\n"
  "  casadi_fill(d->z + p->nx, p->na, 0.);\n"
  "  casadi_copy(lam_x0, p->nx, d->lam);\n"
  "  casadi_copy(lam_a0, p->na, d->lam + p->nx);\n"
  "  casadi_fill(d->lam_lbz, p->nz, 0.);\n"
  "  casadi_fill(d->lam_ubz, p->nz, 0.);\n"
  "}\n"
  "// SYMBOL \"ipqp_reset\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_reset(casadi_ipqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  T1 margin, mid;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Required margin to constraints\n"
  "  margin = .1;\n"
  "  // Reset constraint count\n"
  "  d->n_con = 0;\n"
  "  // Initialize constraints to zero\n"
  "  for (k = p->nx; k < p->nz; ++k) d->z[k] = 0;\n"
  "  // Find interior point\n"
  "  for (k = 0; k < p->nz; ++k) {\n"
  "    if (d->lbz[k] > -p->inf) {\n"
  "      if (d->ubz[k] < p->inf) {\n"
  "        // Both upper and lower bounds\n"
  "        mid = .5 * (d->lbz[k] + d->ubz[k]);\n"
  "        // Ensure margin to boundary, without crossing midpoint\n"
  "        if (d->z[k] < mid) {\n"
  "          d->z[k] = fmin(fmax(d->z[k], d->lbz[k] + margin), mid);\n"
  "        } else if (d->z[k] > mid) {\n"
  "          d->z[k] = fmax(fmin(d->z[k], d->ubz[k] - margin), mid);\n"
  "        }\n"
  "        if (d->ubz[k] > d->lbz[k] + p->dmin) {\n"
  "          d->lam_lbz[k] = 1;\n"
  "          d->lam_ubz[k] = 1;\n"
  "          d->n_con += 2;\n"
  "        }\n"
  "      } else {\n"
  "        // Only lower bound\n"
  "        d->z[k] = fmax(d->z[k], d->lbz[k] + margin);\n"
  "        d->lam_lbz[k] = 1;\n"
  "        d->n_con++;\n"
  "      }\n"
  "    } else {\n"
  "      if (d->ubz[k] < p->inf) {\n"
  "        // Only upper bound\n"
  "        d->z[k] = fmin(d->z[k], d->ubz[k] - margin);\n"
  "        d->lam_ubz[k] = 1;\n"
  "        d->n_con++;\n"
  "      }\n"
  "    }\n"
  "  }\n"
  "  // Clear residual\n"
  "  casadi_clear(d->rz, p->nz);\n"
  "  // Reset iteration counter\n"
  "  d->iter = 0;\n"
  "  // Reset iteration variables\n"
  "  d->msg = 0;\n"
  "  d->tau = -1;\n"
  "}\n"
  "// SYMBOL \"ipqp_diag\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_diag(casadi_ipqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Diagonal entries corresponding to variables\n"
  "  for (k = 0; k < p->nx; ++k) {\n"
  "    if (d->ubz[k] <= d->lbz[k] + p->dmin) {\n"
  "      // Fixed variable (eliminate)\n"
  "      d->D[k] = -1;\n"
  "    } else {\n"
  "      d->D[k] = d->lam_lbz[k] * d->dinv_lbz[k]\n"
  "        + d->lam_ubz[k] * d->dinv_ubz[k];\n"
  "    }\n"
  "  }\n"
  "  // Diagonal entries corresponding to constraints\n"
  "  for (; k < p->nz; ++k) {\n"
  "    if (d->lbz[k] <= -p->inf && d->ubz[k] >= p->inf) {\n"
  "      // Unconstrained (eliminate)\n"
  "      d->D[k] = -1;\n"
  "    } else if (d->ubz[k] <= d->lbz[k] + p->dmin) {\n"
  "      // Equality constrained\n"
  "      d->D[k] = 0;\n"
  "    } else {\n"
  "      d->D[k] = 1. / (d->lam_lbz[k] * d->dinv_lbz[k]\n"
  "        + d->lam_ubz[k] * d->dinv_ubz[k]);\n"
  "    }\n"
  "  }\n"
  "  // Scale diagonal entries\n"
  "  for (k = 0; k < p->nz; ++k) {\n"
  "    if (d->D[k] < 0) {\n"
  "      // Eliminate\n"
  "      d->S[k] = 0;\n"
  "      d->D[k] = 1;\n"
  "    } else {\n"
  "      // Scale\n"
  "      d->S[k] = fmin(1., std::sqrt(1. / d->D[k]));\n"
  "      d->D[k] = fmin(1., d->D[k]);\n"
  "    }\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"ipqp_newiter\"\n"
  "template<typename T1>\n"
  "int casadi_ipqp_newiter(casadi_ipqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Converged?\n"
  "  if (d->pr < p->pr_tol && d->du < p->du_tol && d->co < p->co_tol\n"
  "      && d->mu < p->mu_tol) {\n"
  "    d->status = IPQP_SUCCESS;\n"
  "    return 1;\n"
  "  }\n"
  "  // Max number of iterations reached\n"
  "  if (d->iter >= p->max_iter) {\n"
  "    d->status = IPQP_MAX_ITER;\n"
  "    return 1;\n"
  "  }\n"
  "  // Start new iteration\n"
  "  d->iter++;\n"
  "  // Calculate diagonal entries and scaling factors\n"
  "  casadi_ipqp_diag(d);\n"
  "  // Success\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"ipqp_residual\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_residual(casadi_ipqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  T1 bdiff, viol;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Gradient of the Lagrangian\n"
  "  casadi_axpy(p->nx, 1., d->g, d->rz);\n"
  "  for (k = 0; k < p->nx; ++k) {\n"
  "    if (d->ubz[k] <= d->lbz[k] + p->dmin) {\n"
  "      // Fixed variable: Solve to get multiplier explicitly\n"
  "      d->lam[k] = -d->rz[k];\n"
  "      d->rz[k] = 0;\n"
  "    } else {\n"
  "      // Residual\n"
  "      d->rz[k] += d->lam[k];\n"
  "    }\n"
  "  }\n"
  "  // Constraint violation (only possible for linear constraints)\n"
  "  d->ipr = -1;\n"
  "  d->pr = 0;\n"
  "  for (k = p->nx; k < p->nz; ++k) {\n"
  "    if (d->lbz[k] <= -p->inf && d->ubz[k] >= p->inf) {\n"
  "      // Unconstrained: Solve to get g explicitly\n"
  "      d->z[k] = d->rz[k];\n"
  "      d->lam[k] = 0;\n"
  "    } else {\n"
  "      // Check constraint violation\n"
  "      if (d->rz[k] + d->pr < d->lbz[k]) {\n"
  "        d->pr = d->lbz[k] - d->rz[k];\n"
  "        d->ipr = k;\n"
  "      } else if (d->rz[k] - d->pr > d->ubz[k]) {\n"
  "        d->pr = d->rz[k] - d->ubz[k];\n"
  "        d->ipr = k;\n"
  "      }\n"
  "    }\n"
  "  }\n"
  "  // Dual infeasibility\n"
  "  d->idu = -1;\n"
  "  d->du = 0;\n"
  "  for (k = 0; k < p->nx; ++k) {\n"
  "    if (fabs(d->rz[k]) > d->du) {\n"
  "      d->du = fabs(d->rz[k]);\n"
  "      d->idu = k;\n"
  "    }\n"
  "  }\n"
  "  // Linear constraint\n"
  "  casadi_axpy(p->na, -1., d->z + p->nx, d->rz + p->nx);\n"
  "  // Multiplier consistency\n"
  "  for (k = 0; k < p->nz; ++k) {\n"
  "    if (d->ubz[k] <= d->lbz[k] + p->dmin) {\n"
  "      // Fixed variable: Solve to get lam_lbz, lam_ubz\n"
  "      d->lam_ubz[k] = fmax(d->lam[k], 0.);\n"
  "      d->lam_lbz[k] = fmax(-d->lam[k], 0.);\n"
  "      d->rlam[k] = 0;\n"
  "    } else {\n"
  "      // Residual\n"
  "      d->rlam[k] = d->lam_ubz[k] - d->lam_lbz[k] - d->lam[k];\n"
  "    }\n"
  "  }\n"
  "  // Complementarity conditions, mu\n"
  "  d->mu = 0;\n"
  "  d->ico = -1;\n"
  "  d->co = 0;\n"
  "  for (k = 0; k < p->nz; ++k) {\n"
  "    // Lower bound\n"
  "    if (d->lbz[k] > -p->inf && d->ubz[k] > d->lbz[k] + p->dmin) {\n"
  "      // Inequality constraint\n"
  "      bdiff = d->z[k] - d->lbz[k];\n"
  "      d->mu += d->rlam_lbz[k] = d->lam_lbz[k] * bdiff;\n"
  "      d->dinv_lbz[k] = 1. / bdiff;\n"
  "      // Constraint violation\n"
  "      viol = bdiff * fmax(-d->lam[k], 0.);\n"
  "      if (viol > d->co) {\n"
  "        d->co = viol;\n"
  "        d->ico = k;\n"
  "      }\n"
  "    } else {\n"
  "      // No bound or equality constraint\n"
  "      d->rlam_lbz[k] = 0;\n"
  "      d->dinv_lbz[k] = 0;\n"
  "    }\n"
  "    // Upper bound\n"
  "    if (d->ubz[k] < p->inf && d->ubz[k] > d->lbz[k] + p->dmin) {\n"
  "      // Inequality constraint\n"
  "      bdiff = d->ubz[k] - d->z[k];\n"
  "      d->mu += d->rlam_ubz[k] = d->lam_ubz[k] * bdiff;\n"
  "      d->dinv_ubz[k] = 1. / bdiff;\n"
  "      // Constraint violation\n"
  "      viol = bdiff * fmax(d->lam[k], 0.);\n"
  "      if (viol > d->co) {\n"
  "        d->co = viol;\n"
  "        d->ico = k;\n"
  "      }\n"
  "    } else {\n"
  "      // No bound or equality constraint\n"
  "      d->rlam_ubz[k] = 0;\n"
  "      d->dinv_ubz[k] = 0;\n"
  "    }\n"
  "  }\n"
  "  // Divide mu by total number of finite constraints\n"
  "  if (d->n_con > 0) d->mu /= d->n_con;\n"
  "}\n"
  "// SYMBOL \"ipqp_predictor_prepare\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_predictor_prepare(casadi_ipqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Store r_lam - dinv_lbz * rlam_lbz + dinv_ubz * rlam_ubz in dz\n"
  "  casadi_copy(d->rlam, p->nz, d->dz);\n"
  "  for (k=0; k<p->nz; ++k) d->dz[k] += d->dinv_lbz[k] * d->rlam_lbz[k];\n"
  "  for (k=0; k<p->nz; ++k) d->dz[k] -= d->dinv_ubz[k] * d->rlam_ubz[k];\n"
  "  // Finish calculating x-component of right-hand-side and store in dz[:nx]\n"
  "  for (k=0; k<p->nx; ++k) d->dz[k] += d->rz[k];\n"
  "  // Copy tilde{r}_lam to dlam[nx:] (needed to calculate step in g later)\n"
  "  for (k=p->nx; k<p->nz; ++k) d->dlam[k] = d->dz[k];\n"
  "  // Finish calculating g-component of right-hand-side and store in dz[nx:]\n"
  "  for (k=p->nx; k<p->nz; ++k) {\n"
  "    if (d->S[k] == 0.) {\n"
  "      // Eliminate\n"
  "      d->dz[k] = 0;\n"
  "    } else {\n"
  "      d->dz[k] *= d->D[k] / (d->S[k] * d->S[k]);\n"
  "      d->dz[k] += d->rz[k];\n"
  "    }\n"
  "  }\n"
  "  // Scale and negate right-hand-side\n"
  "  for (k=0; k<p->nz; ++k) d->dz[k] *= -d->S[k];\n"
  "  // dlam_lbz := -rlam_lbz, dlam_ubz := -rlam_ubz\n"
  "  for (k=0; k<p->nz; ++k) d->dlam_lbz[k] = -d->rlam_lbz[k];\n"
  "  for (k=0; k<p->nz; ++k) d->dlam_ubz[k] = -d->rlam_ubz[k];\n"
  "  // dlam_x := rlam_x\n"
  "  for (k=0; k<p->nx; ++k) d->dlam[k] = d->rlam[k];\n"
  "  // Solve to get step\n"
  "  d->linsys = d->dz;\n"
  "}\n"
  "// SYMBOL \"ipqp_maxstep\"\n"
  "template<typename T1>\n"
  "int casadi_ipqp_maxstep(casadi_ipqp_data<T1>* d, T1* alpha, casadi_int* ind) {\n"
  "  // Local variables\n"
  "  T1 test;\n"
  "  casadi_int k, blocking_k;\n"
  "  int flag;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Reset variables\n"
  "  blocking_k = -1;\n"
  "  flag = IPQP_NONE;\n"
  "  // Maximum step size is 1\n"
  "  *alpha = 1.;\n"
  "  // Primal step\n"
  "  for (k=0; k<p->nz; ++k) {\n"
  "    if (d->dz[k] < 0 && d->lbz[k] > -p->inf) {\n"
  "      if ((test = (d->lbz[k] - d->z[k]) / d->dz[k]) < *alpha) {\n"
  "        *alpha = test;\n"
  "        blocking_k = k;\n"
  "        flag = IPQP_PRIMAL | IPQP_LOWER;\n"
  "      }\n"
  "    }\n"
  "    if (d->dz[k] > 0 && d->ubz[k] < p->inf) {\n"
  "      if ((test = (d->ubz[k] - d->z[k]) / d->dz[k]) < *alpha) {\n"
  "        *alpha = test;\n"
  "        blocking_k = k;\n"
  "        flag = IPQP_PRIMAL | IPQP_UPPER;\n"
  "      }\n"
  "    }\n"
  "  }\n"
  "  // Dual step\n"
  "  for (k=0; k<p->nz; ++k) {\n"
  "    if (d->dlam_lbz[k] < 0.) {\n"
  "      if ((test = -d->lam_lbz[k] / d->dlam_lbz[k]) < *alpha) {\n"
  "        *alpha = test;\n"
  "        blocking_k = k;\n"
  "        flag = IPQP_DUAL | IPQP_LOWER;\n"
  "      }\n"
  "    }\n"
  "    if (d->dlam_ubz[k] < 0.) {\n"
  "      if ((test = -d->lam_ubz[k] / d->dlam_ubz[k]) < *alpha) {\n"
  "        *alpha = test;\n"
  "        blocking_k = k;\n"
  "        flag = IPQP_DUAL | IPQP_UPPER;\n"
  "      }\n"
  "    }\n"
  "  }\n"
  "  // Return information about blocking constraints\n"
  "  if (ind) *ind = blocking_k;\n"
  "  return flag;\n"
  "}\n"
  "// SYMBOL \"ipqp_predictor\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_predictor(casadi_ipqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  T1 t, alpha, sigma;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Scale results\n"
  "  for (k=0; k<p->nz; ++k) d->dz[k] *= d->S[k];\n"
  "  // Calculate step in z(g), lam(g)\n"
  "  for (k=p->nx; k<p->nz; ++k) {\n"
  "    if (d->S[k] == 0.) {\n"
  "      // Eliminate\n"
  "      d->dlam[k] = d->dz[k] = 0;\n"
  "    } else {\n"
  "      t = d->D[k] / (d->S[k] * d->S[k]) * (d->dz[k] - d->dlam[k]);\n"
  "      d->dlam[k] = d->dz[k];\n"
  "      d->dz[k] = t;\n"
  "    }\n"
  "  }\n"
  "  // Finish calculation in dlam_lbz, dlam_ubz\n"
  "  for (k=0; k<p->nz; ++k) {\n"
  "    d->dlam_lbz[k] -= d->lam_lbz[k] * d->dz[k];\n"
  "    d->dlam_lbz[k] *= d->dinv_lbz[k];\n"
  "  }\n"
  "  for (k=0; k<p->nz; ++k) {\n"
  "    d->dlam_ubz[k] += d->lam_ubz[k] * d->dz[k];\n"
  "    d->dlam_ubz[k] *= d->dinv_ubz[k];\n"
  "  }\n"
  "  // Finish calculation of dlam(x)\n"
  "  for (k=0; k<p->nx; ++k) d->dlam[k] += d->dlam_ubz[k] - d->dlam_lbz[k];\n"
  "  // Maximum primal and dual step\n"
  "  (void)casadi_ipqp_maxstep(d, &alpha, 0);\n"
  "  // Calculate sigma\n"
  "  sigma = casadi_ipqp_sigma(d, alpha);\n"
  "  // Prepare corrector step\n"
  "  casadi_ipqp_corrector_prepare(d, -sigma * d->mu);\n"
  "  // Solve to get step\n"
  "  d->linsys = d->rz;\n"
  "}\n"
  "// SYMBOL \"ipqp_step\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_step(casadi_ipqp_data<T1>* d, T1 alpha_pr, T1 alpha_du) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Primal step\n"
  "  for (k=0; k<p->nz; ++k) d->z[k] += alpha_pr * d->dz[k];\n"
  "  // Dual step\n"
  "  for (k=0; k<p->nz; ++k) d->lam[k] += alpha_du * d->dlam[k];\n"
  "  for (k=0; k<p->nz; ++k) d->lam_lbz[k] += alpha_du * d->dlam_lbz[k];\n"
  "  for (k=0; k<p->nz; ++k) d->lam_ubz[k] += alpha_du * d->dlam_ubz[k];\n"
  "}\n"
  "// SYMBOL \"ipqp_mu\"\n"
  "template<typename T1>\n"
  "T1 casadi_ipqp_mu(casadi_ipqp_data<T1>* d, T1 alpha) {\n"
  "  // Local variables\n"
  "  T1 mu;\n"
  "  casadi_int k;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Quick return if no inequalities\n"
  "  if (d->n_con == 0) return 0;\n"
  "  // Calculate projected mu (and save to sigma variable)\n"
  "  mu = 0;\n"
  "  for (k = 0; k < p->nz; ++k) {\n"
  "    // Lower bound\n"
  "    if (d->lbz[k] > -p->inf && d->ubz[k] > d->lbz[k] + p->dmin) {\n"
  "      mu += (d->lam_lbz[k] + alpha * d->dlam_lbz[k])\n"
  "        * (d->z[k] - d->lbz[k] + alpha * d->dz[k]);\n"
  "    }\n"
  "    // Upper bound\n"
  "    if (d->ubz[k] < p->inf && d->ubz[k] > d->lbz[k] + p->dmin) {\n"
  "      mu += (d->lam_ubz[k] + alpha * d->dlam_ubz[k])\n"
  "        * (d->ubz[k] - d->z[k] - alpha * d->dz[k]);\n"
  "    }\n"
  "  }\n"
  "  // Divide mu by total number of finite constraints\n"
  "  mu /= d->n_con;\n"
  "  return mu;\n"
  "}\n"
  "// SYMBOL \"ipqp_sigma\"\n"
  "template<typename T1>\n"
  "T1 casadi_ipqp_sigma(casadi_ipqp_data<T1>* d, T1 alpha) {\n"
  "  // Local variables\n"
  "  T1 sigma;\n"
  "  // Quick return if no inequalities\n"
  "  if (d->n_con == 0) return 0;\n"
  "  // Calculate projected mu (and save to sigma variable)\n"
  "  sigma = casadi_ipqp_mu(d, alpha);\n"
  "  // Finish calculation of sigma := (mu_aff / mu)^3\n"
  "  sigma /= d->mu;\n"
  "  sigma *= sigma * sigma;\n"
  "  return sigma;\n"
  "}\n"
  "// SYMBOL \"ipqp_corrector_prepare\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_corrector_prepare(casadi_ipqp_data<T1>* d, T1 shift) {\n"
  "  // Local variables\n"
  "  casadi_int k;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Modified residual in lam_lbz, lam_ubz\n"
  "  for (k=0; k<p->nz; ++k) d->rlam_lbz[k] = d->dlam_lbz[k] * d->dz[k] + shift;\n"
  "  for (k=0; k<p->nz; ++k) d->rlam_ubz[k] = -d->dlam_ubz[k] * d->dz[k] + shift;\n"
  "  // Difference in tilde(r)_x, tilde(r)_lamg\n"
  "  for (k=0; k<p->nz; ++k)\n"
  "    d->rz[k] = d->dinv_lbz[k] * d->rlam_lbz[k]\n"
  "      - d->dinv_ubz[k] * d->rlam_ubz[k];\n"
  "  // Difference in tilde(r)_g\n"
  "  for (k=p->nx; k<p->nz; ++k) {\n"
  "    if (d->S[k] == 0.) {\n"
  "      // Eliminate\n"
  "      d->rlam[k] = d->rz[k] = 0;\n"
  "    } else {\n"
  "      d->rlam[k] = d->rz[k];\n"
  "      d->rz[k] *= d->D[k] / (d->S[k] * d->S[k]);\n"
  "    }\n"
  "  }\n"
  "  // Scale and negate right-hand-side\n"
  "  for (k=0; k<p->nz; ++k) d->rz[k] *= -d->S[k];\n"
  "}\n"
  "// SYMBOL \"ipqp_corrector\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_corrector(casadi_ipqp_data<T1>* d) {\n"
  "  // Local variables\n"
  "  T1 t, mu_test, primal_slack, primal_step, dual_slack, dual_step, max_tau;\n"
  "  casadi_int k;\n"
  "  int flag;\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Scale results\n"
  "  for (k=0; k<p->nz; ++k) d->rz[k] *= d->S[k];\n"
  "  // Calculate step in z(g), lam(g)\n"
  "  for (k=p->nx; k<p->nz; ++k) {\n"
  "    if (d->S[k] == 0.) {\n"
  "      // Eliminate\n"
  "      d->rlam[k] = d->rz[k] = 0;\n"
  "    } else {\n"
  "      t = d->D[k] / (d->S[k] * d->S[k]) * (d->rz[k] - d->rlam[k]);\n"
  "      d->rlam[k] = d->rz[k];\n"
  "      d->rz[k] = t;\n"
  "    }\n"
  "  }\n"
  "  // Update step in dz, dlam\n"
  "  for (k=0; k<p->nz; ++k) d->dz[k] += d->rz[k];\n"
  "  for (k=p->nx; k<p->nz; ++k) d->dlam[k] += d->rlam[k];\n"
  "  // Update step in lam_lbz\n"
  "  for (k=0; k<p->nz; ++k) {\n"
  "    t = d->dinv_lbz[k] * (-d->rlam_lbz[k] - d->lam_lbz[k] * d->rz[k]);\n"
  "    d->dlam_lbz[k] += t;\n"
  "    if (k<p->nx) d->dlam[k] -= t;\n"
  "  }\n"
  "  // Update step in lam_ubz\n"
  "  for (k=0; k<p->nz; ++k) {\n"
  "    t = d->dinv_ubz[k] * (-d->rlam_ubz[k] + d->lam_ubz[k] * d->rz[k]);\n"
  "    d->dlam_ubz[k] += t;\n"
  "    if (k<p->nx) d->dlam[k] += t;\n"
  "  }\n"
  "  // Find the largest step size, keeping track of blocking constraints\n"
  "  flag = casadi_ipqp_maxstep(d, &max_tau, &k);\n"
  "  // Handle blocking constraints using Mehrotra's heuristic\n"
  "  if (flag == IPQP_NONE) {\n"
  "    // No blocking constraints\n"
  "    d->tau = 1;\n"
  "  } else {\n"
  "    // Calculate mu for maximum step\n"
  "    mu_test = casadi_ipqp_mu(d, max_tau);\n"
  "    // Get distance to constraints for blocking variable\n"
  "    if (flag & IPQP_UPPER) {\n"
  "      primal_slack = d->ubz[k] - d->z[k];\n"
  "      primal_step = -d->dz[k];\n"
  "      dual_slack = d->lam_ubz[k];\n"
  "      dual_step = d->dlam_ubz[k];\n"
  "    } else {\n"
  "      primal_slack = d->z[k] - d->lbz[k];\n"
  "      primal_step = d->dz[k];\n"
  "      dual_slack = d->lam_lbz[k];\n"
  "      dual_step = d->dlam_lbz[k];\n"
  "    }\n"
  "    // Mehrotra's heuristic as in in OOQP per communication with S. Wright\n"
  "    if (flag & IPQP_PRIMAL) {\n"
  "      d->tau = (0.01 * mu_test / (dual_slack + max_tau * dual_step)\n"
  "        - primal_slack) / primal_step;\n"
  "    } else {\n"
  "      d->tau = (0.01 * mu_test / (primal_slack + max_tau * primal_step)\n"
  "        - dual_slack) / dual_step;\n"
  "    }\n"
  "    d->tau = fmax(d->tau, 0.99 * max_tau);\n"
  "  }\n"
  "  // Take step\n"
  "  casadi_ipqp_step(d, d->tau, d->tau);\n"
  "  // Clear residual\n"
  "  casadi_clear(d->rz, p->nz);\n"
  "}\n"
  "// SYMBOL \"ipqp\"\n"
  "template<typename T1>\n"
  "int casadi_ipqp(casadi_ipqp_data<T1>* d) {\n"
  "  switch (d->next) {\n"
  "    case IPQP_RESET:\n"
  "      casadi_ipqp_reset(d);\n"
  "      d->task = IPQP_MV;\n"
  "      d->next = IPQP_RESIDUAL;\n"
  "      return 1;\n"
  "    case IPQP_RESIDUAL:\n"
  "      // Calculate residual\n"
  "      if (d->status == IPQP_MV_ERROR) break;\n"
  "      casadi_ipqp_residual(d);\n"
  "      d->task = IPQP_PROGRESS;\n"
  "      d->next = IPQP_NEWITER;\n"
  "      return 1;\n"
  "    case IPQP_NEWITER:\n"
  "      // New iteration\n"
  "      if (d->status == IPQP_PROGRESS_ERROR) break;\n"
  "      if (casadi_ipqp_newiter(d)) break;\n"
  "      d->task = IPQP_FACTOR;\n"
  "      d->next = IPQP_PREPARE;\n"
  "      return 1;\n"
  "    case IPQP_PREPARE:\n"
  "      // Prepare predictor step\n"
  "      if (d->status == IPQP_FACTOR_ERROR) break;\n"
  "      casadi_ipqp_predictor_prepare(d);\n"
  "      d->task = IPQP_SOLVE;\n"
  "      d->next = IPQP_PREDICTOR;\n"
  "      return 1;\n"
  "    case IPQP_PREDICTOR:\n"
  "      // Complete predictor step\n"
  "      if (d->status == IPQP_SOLVE_ERROR) break;\n"
  "      casadi_ipqp_predictor(d);\n"
  "      d->task = IPQP_SOLVE;\n"
  "      d->next = IPQP_CORRECTOR;\n"
  "      return 1;\n"
  "    case IPQP_CORRECTOR:\n"
  "      // Complete predictor step\n"
  "      if (d->status == IPQP_SOLVE_ERROR) break;\n"
  "      casadi_ipqp_corrector(d);\n"
  "      d->task = IPQP_MV;\n"
  "      d->next = IPQP_RESIDUAL;\n"
  "      return 1;\n"
  "    default:\n"
  "      break;\n"
  "  }\n"
  "  // Done iterating\n"
  "  d->next = IPQP_RESET;\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"ipqp_return_status\"\n"
  "inline\n"
  "const char* casadi_ipqp_return_status(casadi_ipqp_flag_t status) {\n"
  "  switch (status) {\n"
  "    case IPQP_SUCCESS: return \"success\";\n"
  "    case IPQP_MAX_ITER: return \"Maximum number of iterations reached\";\n"
  "    case IPQP_NO_SEARCH_DIR: return \"Failed to calculate search direction\";\n"
  "    case IPQP_MV_ERROR: return \"Matrix-vector evaluation error\";\n"
  "    case IPQP_FACTOR_ERROR: return \"Linear solver factorization error\";\n"
  "    case IPQP_SOLVE_ERROR: return \"Linear solver solution error\";\n"
  "    case IPQP_PROGRESS_ERROR: return \"Printing error\";\n"
  "  }\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"ipqp_solution\"\n"
  "template<typename T1>\n"
  "void casadi_ipqp_solution(casadi_ipqp_data<T1>* d, T1* x, T1* lam_x, T1* lam_a) {\n"
  "  // Local variables\n"
  "  const casadi_ipqp_prob<T1>* p = d->prob;\n"
  "  // Copy solution\n"
  "  casadi_copy(d->z, p->nx, x);\n"
  "  casadi_copy(d->lam, p->nx, lam_x);\n"
  "  casadi_copy(d->lam + p->nx, p->na, lam_a);\n"
  "}\n"
  "// SYMBOL \"ipqp_print_header\"\n"
  "template<typename T1>\n"
  "int casadi_ipqp_print_header(casadi_ipqp_data<T1>* d, char* buf, size_t buf_sz) {\n"
  "#ifdef CASADI_SNPRINTF\n"
  "  int flag;\n"
  "  // Print to string\n"
  "  flag = CASADI_SNPRINTF(buf, buf_sz, \"%5s %9s %9s %5s %9s %5s \"\n"
  "          \"%9s %5s %9s %4s\",\n"
  "          \"Iter\", \"mu\", \"|pr|\", \"con\", \"|du|\", \"var\", \"|co|\", \"con\",\n"
  "          \"last_tau\", \"Note\");\n"
  "  // Check if error\n"
  "  if (flag < 0) {\n"
  "    d->status = IPQP_PROGRESS_ERROR;\n"
  "    return 1;\n"
  "  }\n"
  "#else\n"
  "  if (buf_sz) buf[0] = '\\0';\n"
  "#endif\n"
  "  // Successful return\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"ipqp_print_iteration\"\n"
  "template<typename T1>\n"
  "int casadi_ipqp_print_iteration(casadi_ipqp_data<T1>* d, char* buf, int buf_sz) {\n"
  "#ifdef CASADI_SNPRINTF\n"
  "  int flag;\n"
  "  // Print iteration data without note to string\n"
  "  flag = CASADI_SNPRINTF(buf, buf_sz,\n"
  "    \"%5d %9.2g %9.2g %5d %9.2g %5d %9.2g %5d %9.2g  \",\n"
  "    static_cast<int>(d->iter), d->mu,\n"
  "    d->pr, static_cast<int>(d->ipr),\n"
  "    d->du, static_cast<int>(d->idu),\n"
  "    d->co, static_cast<int>(d->ico),\n"
  "    d->tau);\n"
  "  // Check if error\n"
  "  if (flag < 0) {\n"
  "    d->status = IPQP_PROGRESS_ERROR;\n"
  "    return 1;\n"
  "  }\n"
  "  // Rest of buffer reserved for iteration note\n"
  "  buf += flag;\n"
  "  buf_sz -= flag;\n"
  "  // Print iteration note, if any\n"
  "  if (d->msg) {\n"
  "    flag = CASADI_SNPRINTF(buf, buf_sz, \"%s\", d->msg);\n"
  "    // Check if error\n"
  "    if (flag < 0) {\n"
  "      d->status = IPQP_PROGRESS_ERROR;\n"
  "      return 1;\n"
  "    }\n"
  "  }\n"
  "#else\n"
  "  if (buf_sz) buf[0] = '\\0';\n"
  "#endif\n"
  "  // Successful return\n"
  "  return 0;\n"
  "}\n";

const char* casadi_nlp_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"nlpsol_detect_bounds_prob\"\n"
  "template<typename T1>\n"
  "struct casadi_nlpsol_detect_bounds_prob {\n"
  "  casadi_int sz_arg;\n"
  "  casadi_int sz_res;\n"
  "  casadi_int sz_iw;\n"
  "  casadi_int sz_w;\n"
  "  // Original number og constraints\n"
  "  casadi_int ng;\n"
  "  // Number of bounds\n"
  "  casadi_int nb;\n"
  "  const casadi_int *target_x;\n"
  "  const casadi_int *target_g;\n"
  "  const char *is_simple;\n"
  "  int (*callback)(const T1** arg, T1** res, casadi_int* iw, T1* w, void* callback_data);\n"
  "  void* callback_data;\n"
  "};\n"
  "// C-REPLACE \"casadi_nlpsol_detect_bounds_prob<T1>\" \"struct casadi_nlpsol_detect_bounds_prob\"\n"
  "// SYMBOL \"nlpsol_prob\"\n"
  "template<typename T1>\n"
  "struct casadi_nlpsol_prob {\n"
  "  casadi_int nx, ng, np;\n"
  "  casadi_nlpsol_detect_bounds_prob<T1> detect_bounds;\n"
  "};\n"
  "// C-REPLACE \"casadi_nlpsol_prob<T1>\" \"struct casadi_nlpsol_prob\"\n"
  "// SYMBOL \"nlpsol_detect_bounds_data\"\n"
  "template<typename T1>\n"
  "struct casadi_nlpsol_detect_bounds_data {\n"
  "  // Work vectors\n"
  "  const T1** arg;\n"
  "  T1** res;\n"
  "  casadi_int* iw;\n"
  "  T1* w;\n"
  "  // Simple bounds g(x)=A(b)x+b(p);\n"
  "  // a[i]*x[target_x[i]]+b[i]\n"
  "  T1* a;\n"
  "  T1* b;\n"
  "  casadi_int* target_l;\n"
  "  casadi_int* target_u;\n"
  "  T1* lam_xl;\n"
  "  T1* lam_xu;\n"
  "};\n"
  "// C-REPLACE \"casadi_nlpsol_detect_bounds_data<T1>\" \"struct casadi_nlpsol_detect_bounds_data\"\n"
  "// C-REPLACE \"casadi_oracle_data<T1>\" \"struct casadi_oracle_data\"\n"
  "// SYMBOL \"nlpsol_data\"\n"
  "template<typename T1>\n"
  "struct casadi_nlpsol_data {\n"
  "  // Problem structure\n"
  "  const casadi_nlpsol_prob<T1>* prob;\n"
  "  casadi_oracle_data<T1>* oracle;\n"
  "  // Variable bounds\n"
  "  T1 *lbz, *ubz;\n"
  "  // Current primal solution\n"
  "  T1 *z;\n"
  "  // Current dual solution\n"
  "  T1 *lam;\n"
  "  // Storage for f when null pointer passed\n"
  "  T1 objective;\n"
  "  // NLP data, pointers to arg (no allocations needed)\n"
  "  const T1 *p, *lbx, *ubx, *lbg, *ubg, *x0, *lam_x0, *lam_g0;\n"
  "  // NLP results, pointers to res (no allocations needed)\n"
  "  T1 *f, *x, *g, *lam_x, *lam_g, *lam_p;\n"
  "  casadi_nlpsol_detect_bounds_data<T1> detect_bounds;\n"
  "};\n"
  "// C-REPLACE \"casadi_nlpsol_data<T1>\" \"struct casadi_nlpsol_data\"\n"
  "// SYMBOL \"nlpsol_work\"\n"
  "template<typename T1>\n"
  "void casadi_nlpsol_work(const casadi_nlpsol_prob<T1>* p, casadi_int* sz_arg, casadi_int* sz_res,\n"
  "    casadi_int* sz_iw, casadi_int* sz_w) {\n"
  "  // Reset sz_arg, sz_res\n"
  "  *sz_arg = *sz_res = 0;\n"
  "  // Reset sz_w, sz_iw\n"
  "  *sz_w = *sz_iw = 0;\n"
  "  *sz_w += p->nx + p->ng; // z\n"
  "  *sz_w += p->nx + p->ng; // lbz\n"
  "  *sz_w += p->nx + p->ng; // ubz\n"
  "  *sz_w += p->nx + p->ng; // lam\n"
  "  if (p->detect_bounds.ng) {\n"
  "    *sz_arg += p->detect_bounds.sz_arg;\n"
  "    *sz_res += p->detect_bounds.sz_res;\n"
  "    *sz_iw += p->detect_bounds.sz_iw;\n"
  "    *sz_w += p->detect_bounds.sz_w;\n"
  "    *sz_w += p->detect_bounds.nb; // a;\n"
  "    *sz_w += p->detect_bounds.nb; // b;\n"
  "    *sz_iw += p->nx; // target_l\n"
  "    *sz_iw += p->nx; // target_u\n"
  "    *sz_w += p->nx; // lam_xl;\n"
  "    *sz_w += p->nx; // lam_xu;\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"nlpsol_init\"\n"
  "template<typename T1>\n"
  "void casadi_nlpsol_init(casadi_nlpsol_data<T1>* d, const T1*** arg, T1*** res,\n"
  "    casadi_int** iw, T1** w) {\n"
  "  // Local variables\n"
  "  casadi_int nx, ng;\n"
  "  const casadi_nlpsol_prob<T1>* p = d->prob;\n"
  "  nx = p->nx;\n"
  "  ng = p->ng;\n"
  "  // Get matrix number of nonzeros\n"
  "  d->z = *w; *w += nx + ng;\n"
  "  d->lbz = *w; *w += nx + ng;\n"
  "  d->ubz = *w; *w += nx + ng;\n"
  "  d->lam = *w; *w += nx + ng;\n"
  "  if (p->detect_bounds.ng) {\n"
  "    d->detect_bounds.arg = *arg; *arg += p->detect_bounds.sz_arg;\n"
  "    d->detect_bounds.res = *res; *res += p->detect_bounds.sz_res;\n"
  "    d->detect_bounds.iw = *iw; *iw += p->detect_bounds.sz_iw;\n"
  "    d->detect_bounds.w = *w; *w += p->detect_bounds.sz_w;\n"
  "    d->detect_bounds.a = *w; *w += p->detect_bounds.nb;\n"
  "    d->detect_bounds.b = *w; *w += p->detect_bounds.nb;\n"
  "    d->detect_bounds.target_l = *iw; *iw += p->nx;\n"
  "    d->detect_bounds.target_u = *iw; *iw += p->nx;\n"
  "    d->detect_bounds.lam_xl = *w; *w += nx;\n"
  "    d->detect_bounds.lam_xu = *w; *w += nx;\n"
  "  }\n"
  "}\n"
  "// SYMBOL \"nlpsol_detect_bounds_before\"\n"
  "template<typename T1>\n"
  "int casadi_detect_bounds_before(casadi_nlpsol_data<T1>* d_nlp) {\n"
  "  const casadi_nlpsol_prob<T1>* p_nlp = d_nlp->prob;\n"
  "  casadi_nlpsol_detect_bounds_data<T1>* d_bounds = &d_nlp->detect_bounds;\n"
  "  const casadi_nlpsol_detect_bounds_prob<T1>* p_bounds = &p_nlp->detect_bounds;\n"
  "  casadi_int nx = p_nlp->nx;\n"
  "  d_bounds->arg[0] = d_nlp->z;\n"
  "  d_bounds->arg[1] = d_nlp->p;\n"
  "  d_bounds->res[0] = d_bounds->a;\n"
  "  d_bounds->res[1] = d_bounds->b;\n"
  "  p_bounds->callback(d_bounds->arg, d_bounds->res,\n"
  "    d_bounds->iw, d_bounds->w, p_bounds->callback_data);\n"
  "  for (casadi_int i=0;i<p_bounds->nb;++i) {\n"
  "    if (d_bounds->a[i]==0) {\n"
  "      casadi_int k = p_bounds->target_g[i];\n"
  "      if (d_nlp->lbg[k]>d_bounds->b[i]) return 1;\n"
  "      if (d_nlp->ubg[k]<d_bounds->b[i]) return 1;\n"
  "    }\n"
  "  }\n"
  "  T1* lbz = d_nlp->lbz+nx;\n"
  "  T1* ubz = d_nlp->ubz+nx;\n"
  "  T1* lam = d_nlp->lam+nx;\n"
  "  for (casadi_int i=0;i<nx;++i) {\n"
  "    d_bounds->lam_xl[i] = d_nlp->lam_x0 ? (d_nlp->lam_x0[i]<0)*d_nlp->lam_x0[i] : 0.;\n"
  "    d_bounds->lam_xu[i] = d_nlp->lam_x0 ? (d_nlp->lam_x0[i]>0)*d_nlp->lam_x0[i] : 0.;\n"
  "  }\n"
  "  for (casadi_int i=0;i<nx;++i) {\n"
  "    d_bounds->target_l[i] = i;\n"
  "    d_bounds->target_u[i] = i;\n"
  "  }\n"
  "  // Update lbz/ubz\n"
  "  casadi_int k=0;\n"
  "  for (casadi_int i=0;i<p_bounds->ng;++i) {\n"
  "    if (p_bounds->is_simple[i]) {\n"
  "      // Update lbz/ubz\n"
  "      T1 lb = (d_nlp->lbg[i]-d_bounds->b[k])/d_bounds->a[k];\n"
  "      T1 ub = (d_nlp->ubg[i]-d_bounds->b[k])/d_bounds->a[k];\n"
  "      if (d_bounds->a[k]<0) {\n"
  "        T1 tmp = lb;\n"
  "        lb = ub;\n"
  "        ub = tmp;\n"
  "      }\n"
  "      casadi_int j = p_bounds->target_x[k];\n"
  "      lb += d_nlp->z[j];\n"
  "      ub += d_nlp->z[j];\n"
  "      if (lb==d_nlp->lbz[j]) {\n"
  "        if (d_nlp->lam_g0) d_bounds->lam_xl[j] += (d_nlp->lam_g0[i]<0)*d_nlp->lam_g0[i];\n"
  "      } else if (lb>d_nlp->lbz[j]) {\n"
  "        d_nlp->lbz[j] = lb;\n"
  "        d_bounds->target_l[j] = nx+i;\n"
  "        if (d_nlp->lam_g0) d_bounds->lam_xl[j] = (d_nlp->lam_g0[i]<0)*d_nlp->lam_g0[i];\n"
  "      }\n"
  "      if (ub==d_nlp->ubz[j]) {\n"
  "        if (d_nlp->lam_g0) d_bounds->lam_xu[j] += (d_nlp->lam_g0[i]>0)*d_nlp->lam_g0[i];\n"
  "      } else if (ub<d_nlp->ubz[j]) {\n"
  "        d_nlp->ubz[j] = ub;\n"
  "        d_bounds->target_u[j] = nx+i;\n"
  "        if (d_nlp->lam_g0) d_bounds->lam_xu[j] = (d_nlp->lam_g0[i]>0)*d_nlp->lam_g0[i];\n"
  "      }\n"
  "      k++;\n"
  "    } else {\n"
  "      // Update lbz/ubz\n"
  "      *lbz++ = d_nlp->lbg[i];\n"
  "      *ubz++ = d_nlp->ubg[i];\n"
  "      if (d_nlp->lam_g0) *lam++ = d_nlp->lam_g0[i];\n"
  "    }\n"
  "  }\n"
  "  for (casadi_int i=0;i<nx;++i) {\n"
  "    d_nlp->lam[i] = d_bounds->lam_xl[i]+d_bounds->lam_xu[i];\n"
  "  }\n"
  "  return 0;\n"
  "}\n"
  "// SYMBOL \"nlpsol_detect_bounds_after\"\n"
  "template<typename T1>\n"
  "int casadi_detect_bounds_after(casadi_nlpsol_data<T1>* d_nlp) {\n"
  "  const casadi_nlpsol_prob<T1>* p_nlp = d_nlp->prob;\n"
  "  casadi_nlpsol_detect_bounds_data<T1>* d_bounds = &d_nlp->detect_bounds;\n"
  "  const casadi_nlpsol_detect_bounds_prob<T1>* p_bounds = &p_nlp->detect_bounds;\n"
  "  casadi_int nx = p_nlp->nx;\n"
  "  casadi_fill(d_nlp->lam_x, nx, 0.);\n"
  "  casadi_fill(d_nlp->lam_g, p_bounds->ng, 0.);\n"
  "  casadi_int k = 0;\n"
  "  casadi_int k_normal = 0;\n"
  "  for (casadi_int i=0;i<p_bounds->ng;++i) {\n"
  "    if (p_bounds->is_simple[i]) {\n"
  "      casadi_int j = p_bounds->target_x[k];\n"
  "      if (d_nlp->g) {\n"
  "        d_nlp->g[i] = d_bounds->a[k]*d_nlp->z[j]-d_bounds->b[k];\n"
  "        if (d_nlp->x0) d_nlp->g[i] += d_nlp->x0[j];\n"
  "      }\n"
  "      k++;\n"
  "    } else {\n"
  "      if (d_nlp->g) d_nlp->g[i] = d_nlp->z[nx+k_normal];\n"
  "      if (d_nlp->lam_g) d_nlp->lam_g[i] = d_nlp->lam[nx+k_normal];\n"
  "      k_normal++;\n"
  "    }\n"
  "  }\n"
  "  for (casadi_int i=0;i<nx;++i) {\n"
  "    if (d_bounds->target_l[i]<nx) {\n"
  "      if (d_nlp->lam_x) d_nlp->lam_x[i] += (d_nlp->lam[i]<0)*d_nlp->lam[i];\n"
  "    } else {\n"
  "      if (d_nlp->lam_g)\n"
  "        d_nlp->lam_g[d_bounds->target_l[i]-nx] += (d_nlp->lam[i]<0)*d_nlp->lam[i];\n"
  "    }\n"
  "    if (d_bounds->target_u[i]<nx) {\n"
  "      if (d_nlp->lam_x) d_nlp->lam_x[i] += (d_nlp->lam[i]>0)*d_nlp->lam[i];\n"
  "    } else {\n"
  "      if (d_nlp->lam_g)\n"
  "        d_nlp->lam_g[d_bounds->target_u[i]-nx] += (d_nlp->lam[i]>0)*d_nlp->lam[i];\n"
  "    }\n"
  "  }\n"
  "  k = 0;\n"
  "  for (casadi_int i=0;i<p_bounds->ng;++i) {\n"
  "    if (p_bounds->is_simple[i]) {\n"
  "      if (d_nlp->lam_g) d_nlp->lam_g[i] /= d_bounds->a[k];\n"
  "      k++;\n"
  "    }\n"
  "  }\n"
  "  return 0;\n"
  "}\n";

const char* casadi_sqpmethod_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// C-REPLACE \"casadi_nlpsol_prob<T1>\" \"struct casadi_nlpsol_prob\"\n"
  "// SYMBOL \"sqpmethod_prob\"\n"
  "template<typename T1>\n"
  "struct casadi_sqpmethod_prob {\n"
  "  const casadi_nlpsol_prob<T1>* nlp;\n"
  "  // Sparsity patterns\n"
  "  const casadi_int *sp_h, *sp_a, *sp_hr;\n"
  "  casadi_int merit_memsize;\n"
  "  casadi_int max_iter_ls;\n"
  "};\n"
  "// C-REPLACE \"casadi_sqpmethod_prob<T1>\" \"struct casadi_sqpmethod_prob\"\n"
  "// SYMBOL \"sqpmethod_data\"\n"
  "template<typename T1>\n"
  "struct casadi_sqpmethod_data {\n"
  "  // Problem structure\n"
  "  const casadi_sqpmethod_prob<T1>* prob;\n"
  "  T1* z_cand;\n"
  "  // Lagrange gradient in the next iterate\n"
  "  T1 *gLag, *gLag_old;\n"
  "  // Gradient of the objective\n"
  "  T1 *gf;\n"
  "  // Bounds of the QP\n"
  "  T1 *lbdz, *ubdz;\n"
  "  // QP solution\n"
  "  T1 *dx, *dlam;\n"
  "  // Hessian approximation\n"
  "  T1 *Bk;\n"
  "  // Jacobian\n"
  "  T1* Jk;\n"
  "  // merit_mem\n"
  "  T1* merit_mem;\n"
  "  // temp_mem\n"
  "  T1* temp_mem;\n"
  "  // temp_sol\n"
  "  T1* temp_sol;\n"
  "  const T1** arg;\n"
  "  T1** res;\n"
  "  casadi_int* iw;\n"
  "  T1* w;\n"
  "};\n"
  "// C-REPLACE \"casadi_sqpmethod_data<T1>\" \"struct casadi_sqpmethod_data\"\n"
  "// SYMBOL \"sqpmethod_work\"\n"
  "template<typename T1>\n"
  "void casadi_sqpmethod_work(const casadi_sqpmethod_prob<T1>* p,\n"
  "    casadi_int* sz_iw, casadi_int* sz_w, int elastic_mode, int so_corr) {\n"
  "  // Local variables\n"
  "  casadi_int nnz_h, nnz_a, nx, ng;\n"
  "  nnz_h = p->sp_h[2+p->sp_h[1]];\n"
  "  nnz_a = p->sp_a[2+p->sp_a[1]];\n"
  "  nx = p->nlp->nx;\n"
  "  ng = p->nlp->ng;\n"
  "  // Reset sz_w, sz_iw\n"
  "  *sz_w = *sz_iw = 0;\n"
  "  if (p->max_iter_ls>0 || so_corr) *sz_w += nx + ng; // z_cand\n"
  "  // Lagrange gradient in the next iterate\n"
  "  *sz_w += nx; // gLag\n"
  "  *sz_w += nx; // gLag_old\n"
  "  // Gradient of the objective\n"
  "  *sz_w += nx; // gf\n"
  "  // Bounds of the QP\n"
  "  *sz_w += nx + ng; // lbdz\n"
  "  *sz_w += nx + ng; // ubdz\n"
  "  // QP solution\n"
  "  *sz_w += nx; // dx\n"
  "  *sz_w += nx + ng; // dlam\n"
  "  // Hessian approximation\n"
  "  *sz_w += nnz_h; // Bk\n"
  "  // Jacobian\n"
  "  *sz_w += nnz_a; // Jk\n"
  "  // merit_mem\n"
  "  if (p->max_iter_ls>0 || so_corr) *sz_w += p->merit_memsize;\n"
  "  if (elastic_mode) {\n"
  "    // Additional work for larger objective gradient\n"
  "    *sz_w += 2*ng; // gf\n"
  "    // Additional work for the larger bounds\n"
  "    *sz_w += 2*ng; // lbdz\n"
  "    *sz_w += 2*ng; // ubdz\n"
  "    // Additional work for larger solution\n"
  "    *sz_w += 2*ng; // dx\n"
  "    *sz_w += 2*ng; // dlam\n"
  "    // Additional work for larger jacobian\n"
  "    *sz_w += 2*ng; // Jk\n"
  "    // Additional work for temp memory\n"
  "    *sz_w += ng;\n"
  "  }\n"
  "  if (so_corr) *sz_w += nx+nx+ng; // Temp memory for failing soc\n"
  "}\n"
  "// SYMBOL \"sqpmethod_init\"\n"
  "template<typename T1>\n"
  "void casadi_sqpmethod_init(casadi_sqpmethod_data<T1>* d,\n"
  "    const T1*** arg, T1*** res, casadi_int** iw, T1** w,\n"
  "    int elastic_mode, int so_corr) {\n"
  "  // Local variables\n"
  "  casadi_int nnz_h, nnz_a, nx, ng;\n"
  "  const casadi_sqpmethod_prob<T1>* p = d->prob;\n"
  "  // Get matrix number of nonzeros\n"
  "  nnz_h = p->sp_h[2+p->sp_h[1]];\n"
  "  nnz_a = p->sp_a[2+p->sp_a[1]];\n"
  "  nx = p->nlp->nx;\n"
  "  ng = p->nlp->ng;\n"
  "  if (p->max_iter_ls>0 || so_corr) {\n"
  "    d->z_cand = *w; *w += nx + ng;\n"
  "  }\n"
  "  // Lagrange gradient in the next iterate\n"
  "  d->gLag = *w; *w += nx;\n"
  "  d->gLag_old = *w; *w += nx;\n"
  "  // Hessian approximation\n"
  "  d->Bk = *w; *w += nnz_h;\n"
  "  // merit_mem\n"
  "  if (p->max_iter_ls>0 || so_corr) {\n"
  "    d->merit_mem = *w; *w += p->merit_memsize;\n"
  "  }\n"
  "  if (so_corr) {\n"
  "    d->temp_sol = *w; *w += nx+nx+ng;\n"
  "  }\n"
  "  if (elastic_mode) {\n"
  "    // Gradient of the objective\n"
  "    d->gf = *w; *w += nx + 2*ng;\n"
  "    // Bounds of the QP\n"
  "    d->lbdz = *w; *w += nx + 3*ng;\n"
  "    d->ubdz = *w; *w += nx + 3*ng;\n"
  "    // QP solution\n"
  "    d->dx = *w; *w += nx + 2*ng;\n"
  "    d->dlam = *w; *w += nx + 3*ng;\n"
  "    // Jacobian\n"
  "    d->Jk = *w; *w += nnz_a + 2*ng;\n"
  "    // temp mem\n"
  "    d->temp_mem = *w; *w += ng;\n"
  "  } else {\n"
  "    // Gradient of the objective\n"
  "    d->gf = *w; *w += nx;\n"
  "    // Bounds of the QP\n"
  "    d->lbdz = *w; *w += nx + ng;\n"
  "    d->ubdz = *w; *w += nx + ng;\n"
  "    // QP solution\n"
  "    d->dx = *w; *w += nx;\n"
  "    d->dlam = *w; *w += nx + ng;\n"
  "    // Jacobian\n"
  "    d->Jk = *w; *w += nnz_a;\n"
  "  }\n"
  "  d->arg = *arg;\n"
  "  d->res = *res;\n"
  "  d->iw = *iw;\n"
  "  d->w = *w;\n"
  "}\n";

const char* casadi_bfgs_str =
  "// NOLINT(legal/copyright)\n"
  "// SYMBOL \"bfgs\"\n"
  "// BFGS update\n"
  "template<typename T1>\n"
  "void casadi_bfgs(const casadi_int* sp_h, T1* h, const T1* dx,\n"
  "                 const T1* glag, const T1* glag_old, T1* w) {\n"
  "  // Local variables\n"
  "  casadi_int nx;\n"
  "  T1 *yk, *qk, dxBkdx, omega, theta, phi;\n"
  "  // Dimension\n"
  "  nx = sp_h[0];\n"
  "  // Work vectors\n"
  "  yk = w; w += nx;\n"
  "  qk = w; w += nx;\n"
  "  // yk = glag - glag_old\n"
  "  casadi_copy(glag, nx, yk);\n"
  "  casadi_axpy(nx, -1., glag_old, yk);\n"
  "  // qk = H*dx\n"
  "  casadi_clear(qk, nx);\n"
  "  casadi_mv(h, sp_h, dx, qk, 0);\n"
  "  // Calculating theta\n"
  "  dxBkdx = casadi_dot(nx, dx, qk);\n"
  "  // C-REPLACE \"if_else\" \"casadi_if_else\"\n"
  "  omega = if_else(casadi_dot(nx, yk, dx) < 0.2 * casadi_dot(nx, dx, qk),\n"
  "                  0.8 * dxBkdx / (dxBkdx - casadi_dot(nx, dx, yk)), 1);\n"
  "  // yk = omega * yk + (1 - omega) * qk;\n"
  "  casadi_scal(nx, omega, yk);\n"
  "  casadi_axpy(nx, 1 - omega, qk, yk);\n"
  "  theta = 1. / casadi_dot(nx, dx, yk);\n"
  "  phi = 1. / casadi_dot(nx, qk, dx);\n"
  "  // Update H\n"
  "  casadi_rank1(h, sp_h, theta, yk, yk);\n"
  "  casadi_rank1(h, sp_h, -phi, qk, qk);\n"
  "}\n"
  "// SYMBOL \"bfgs_reset\"\n"
  "// Removes off-diagonal entries\n"
  "template<typename T1>\n"
  "void casadi_bfgs_reset(const casadi_int* sp_h, T1* h) {\n"
  "  casadi_int ncol, c, k;\n"
  "  const casadi_int *colind, *row;\n"
  "  ncol = sp_h[1];\n"
  "  colind = sp_h+2; row = sp_h+ncol+3;\n"
  "  for (c=0; c<ncol; ++c) {\n"
  "    for (k=colind[c]; k<colind[c+1]; ++k) {\n"
  "      if (c!=row[k]) h[k] = 0;\n"
  "    }\n"
  "  }\n"
  "}\n";

const char* casadi_regularize_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// C-REPLACE \"fmin\" \"casadi_fmin\"\n"
  "// SYMBOL \"lb_eig\"\n"
  "// Use Gershgorin to finds upper and lower bounds on the eigenvalues\n"
  "template<typename T1>\n"
  "T1 casadi_lb_eig(const casadi_int* sp_h, const T1* h) {\n"
  "  // Local variables\n"
  "  casadi_int ncol, c, k;\n"
  "  T1 center, radius;\n"
  "  const casadi_int *colind, *row;\n"
  "  // Return value\n"
  "  T1 lb_eig = 0;\n"
  "  // Get sparsity\n"
  "  ncol = sp_h[1];\n"
  "  colind = sp_h+2; row = sp_h+ncol+3;\n"
  "  for (c=0; c<ncol; ++c) {\n"
  "    // Calculate Gershgorin discs\n"
  "    center = 0;\n"
  "    radius = 0;\n"
  "    for (k=colind[c]; k<colind[c+1]; ++k) {\n"
  "      if (row[k]==c) {\n"
  "        center = h[k];\n"
  "      } else {\n"
  "        radius += fabs(h[k]);\n"
  "      }\n"
  "    }\n"
  "    // Update the eigenvalue estimates\n"
  "    if (c==0) {\n"
  "      lb_eig = center - radius;\n"
  "    } else {\n"
  "      lb_eig = fmin(lb_eig, center - radius);\n"
  "    }\n"
  "  }\n"
  "  return lb_eig;\n"
  "}\n"
  "// SYMBOL \"regularize\"\n"
  "// Add a multiple of the identity matrix to the diagonal\n"
  "template<typename T1>\n"
  "void casadi_regularize(const casadi_int* sp_h, T1* h, T1 reg) {\n"
  "  // Local variables\n"
  "  casadi_int ncol, c, k;\n"
  "  const casadi_int *colind, *row;\n"
  "  // Get sparsity\n"
  "  ncol = sp_h[1];\n"
  "  colind = sp_h+2; row = sp_h+ncol+3;\n"
  "  // Shift diagonal entries\n"
  "  for (c=0; c<ncol; ++c) {\n"
  "    for (k=colind[c]; k<colind[c+1]; ++k) {\n"
  "      if (row[k]==c) h[k] += reg;\n"
  "    }\n"
  "  }\n"
  "}\n";

const char* casadi_newton_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"newton_mem\"\n"
  "template<typename T1>\n"
  "struct casadi_newton_mem {\n"
  "  casadi_int n;\n"
  "  T1 abstol;\n"
  "  T1 abstol_step;\n"
  "  T1* x;\n"
  "  T1* g;\n"
  "  T1* jac_g_x;\n"
  "  const casadi_int* sp_a;\n"
  "  const casadi_int* sp_v;\n"
  "  const casadi_int* sp_r;\n"
  "  const casadi_int* prinv;\n"
  "  const casadi_int* pc;\n"
  "  T1* lin_w;\n"
  "  T1* lin_v;\n"
  "  T1* lin_r;\n"
  "  T1* lin_beta;\n"
  "};\n"
  "// C-REPLACE \"casadi_newton_mem<T1>\" \"struct casadi_newton_mem\"\n"
  "// SYMBOL \"newton\"\n"
  "template<typename T1>\n"
  "int casadi_newton(const casadi_newton_mem<T1>* m) {\n"
  "    // Check tolerance on residual\n"
  "    if (m->abstol>0 && casadi_norm_inf(m->n, m->g) <= m->abstol) return 1;\n"
  "    // Factorize J\n"
  "    casadi_qr(m->sp_a, m->jac_g_x, m->lin_w,\n"
  "              m->sp_v,  m->lin_v, m->sp_r, m->lin_r, m->lin_beta,\n"
  "              m->prinv, m->pc);\n"
  "    // Solve J^(-1) g\n"
  "    casadi_qr_solve(m->g, 1, 0, m->sp_v, m->lin_v, m->sp_r, m->lin_r, m->lin_beta,\n"
  "                    m->prinv, m->pc, m->lin_w);\n"
  "    // Update Xk+1 = Xk - J^(-1) g\n"
  "    casadi_axpy(m->n, -1., m->g, m->x);\n"
  "    // Check tolerance on step\n"
  "    if (m->abstol_step>0 && casadi_norm_inf(m->n, m->g) <= m->abstol_step) return 2;\n"
  "    // We will need another newton step\n"
  "    return 0;\n"
  "}\n";

const char* casadi_bound_consistency_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// C-REPLACE \"fmax\" \"casadi_fmax\"\n"
  "// C-REPLACE \"fmin\" \"casadi_fmin\"\n"
  "// C-REPLACE \"std::isinf\" \"casadi_isinf\"\n"
  "// SYMBOL \"bound_consistency\"\n"
  "template<typename T1>\n"
  "void casadi_bound_consistency(casadi_int n, T1* x, T1* lam,\n"
  "                                 const T1* lbx, const T1* ubx) {\n"
  "    // Local variables\n"
  "    casadi_int i;\n"
  "    T1 lb, ub;\n"
  "    // Loop over variables\n"
  "    for (i=0; i<n; ++i) {\n"
  "      // Get bounds\n"
  "      lb = lbx ? lbx[i] : 0.;\n"
  "      ub = ubx ? ubx[i] : 0.;\n"
  "      // Make sure bounds are respected\n"
  "      x[i] = fmin(fmax(x[i], lb), ub);\n"
  "      // Adjust multipliers\n"
  "      if (std::isinf(lb) && std::isinf(ub)) {\n"
  "        // Both multipliers are infinite\n"
  "        lam[i] = 0.;\n"
  "      } else if (std::isinf(lb) || x[i] - lb > ub - x[i]) {\n"
  "        // Infinite lower bound or closer to upper bound than lower bound\n"
  "        lam[i] = fmax(0., lam[i]);\n"
  "      } else if (std::isinf(ub) || x[i] - lb < ub - x[i]) {\n"
  "        // Infinite upper bound or closer to lower bound than upper bound\n"
  "        lam[i] = fmin(0., lam[i]);\n"
  "      }\n"
  "    }\n"
  "}\n";

const char* casadi_lsqr_str =
  "// C-REPLACE \"fabs\" \"casadi_fabs\"\n"
  "// C-REPLACE \"sign\" \"casadi_sign\"\n"
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"lsqr_sym_ortho\"\n"
  "template<typename T1>\n"
  "void casadi_lsqr_sym_ortho(T1 a, T1 b, T1* cs, T1* sn, T1* rho) {\n"
  "    T1 tau;\n"
  "    if (b == 0) {\n"
  "        *cs = sign(a);\n"
  "        *sn = 0;\n"
  "        *rho = fabs(a);\n"
  "    } else if (a==0) {\n"
  "        *cs = 0;\n"
  "        *sn = sign(b);\n"
  "        *rho = fabs(b);\n"
  "    } else if (fabs(b)>fabs(a)) {\n"
  "        tau = a/b;\n"
  "        *sn = sign(b)/sqrt(1+tau*tau);\n"
  "        *cs = (*sn)*tau;\n"
  "        *rho = b/(*sn);\n"
  "    } else {\n"
  "        tau = b/a;\n"
  "        *cs = sign(a)/sqrt(1+tau*tau);\n"
  "        *sn = (*cs)*tau;\n"
  "        *rho = a/(*cs);\n"
  "    }\n"
  "}\n"
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"lsqr_single_solve\"\n"
  "// Ref: scipy\n"
  "template<typename T1>\n"
  "int casadi_lsqr_single_solve(const T1* A, T1* x, casadi_int tr, const casadi_int* sp, T1* w) {\n"
  "    casadi_int m, n, i;\n"
  "    T1 damp, atol, btol, conlim, ctol, anorm, acond, dampsq, ddnorm, res2, xnorm, xxnorm, z;\n"
  "    T1 cs2, sn2, alpha, beta, rhobar, phibar, bnorm, rnorm, arnorm, rhobar1, cs1, sn1, psi;\n"
  "    T1 cs, sn, rho, theta, phi, tau, t1, t2, n2dk, delta, gambar, rhs, zbar, gamma, res1;\n"
  "    T1 r1sq, r1norm, test1, test2, test3, rtol;\n"
  "    casadi_int iter_lim, itn, istop;\n"
  "    T1 *u, *v, *xx, *ww, *dk;\n"
  "    m = sp[0];\n"
  "    n = sp[1];\n"
  "    damp = 0;\n"
  "    atol = 1e-15;\n"
  "    btol = 1e-15;\n"
  "    conlim = 1e8;\n"
  "    iter_lim = 10000;\n"
  "    itn = 0;\n"
  "    istop = 0;\n"
  "    ctol = 0;\n"
  "    if (conlim > 0) ctol = 1/conlim;\n"
  "    anorm = 0;\n"
  "    acond = 0;\n"
  "    dampsq = damp*damp;\n"
  "    ddnorm = 0;\n"
  "    res2 = 0;\n"
  "    xnorm = 0;\n"
  "    xxnorm = 0;\n"
  "    z = 0;\n"
  "    cs2 = -1;\n"
  "    sn2 = 0;\n"
  "    u = w;  w+= m; casadi_copy(x, m, u);\n"
  "    v = w;  w+= n; casadi_clear(v, n);\n"
  "    xx = w; w+= n; casadi_clear(xx, n);\n"
  "    ww = w; w+= n; casadi_clear(v, n);\n"
  "    dk = w; w+= n;\n"
  "    alpha = 0;\n"
  "    beta = casadi_norm_2(m, u);\n"
  "    if (beta>0) {\n"
  "      for (i=0;i<m;++i) u[i]*=1/beta;\n"
  "      casadi_mv(A, sp, u, v, !tr);\n"
  "      alpha = casadi_norm_2(n, v);\n"
  "    }\n"
  "    if (alpha>0) {\n"
  "      for (i=0;i<n;++i) v[i]*=1/alpha;\n"
  "      casadi_copy(v, n, ww);\n"
  "    }\n"
  "    rhobar = alpha;\n"
  "    phibar = beta;\n"
  "    bnorm = beta;\n"
  "    rnorm = beta;\n"
  "    arnorm = alpha * beta;\n"
  "    if (arnorm==0.0) {\n"
  "      casadi_clear(x, m);\n"
  "      return 0;\n"
  "    }\n"
  "    while (itn<iter_lim) {\n"
  "      itn++;\n"
  "      for (i=0;i<m;++i) u[i]*=-alpha;\n"
  "      casadi_mv(A, sp, v, u, tr);\n"
  "      beta = casadi_norm_2(m, u);\n"
  "      if (beta>0) {\n"
  "        for (i=0;i<m;++i) u[i]*=1/beta;\n"
  "        anorm = sqrt(anorm*anorm + alpha*alpha+beta*beta+damp*damp);\n"
  "        for (i=0;i<n;++i) v[i]*=-beta;\n"
  "        casadi_mv(A, sp, u, v, !tr);\n"
  "        alpha = casadi_norm_2(n, v);\n"
  "        if (alpha>0) for (i=0;i<n;++i) v[i]*=1/alpha;\n"
  "      }\n"
  "      rhobar1 = sqrt(rhobar*rhobar+damp*damp);\n"
  "      cs1 = rhobar / rhobar1;\n"
  "      sn1 = damp / rhobar1;\n"
  "      psi = sn1 * phibar;\n"
  "      phibar *= cs1;\n"
  "      casadi_lsqr_sym_ortho(rhobar1, beta, &cs, &sn, &rho);\n"
  "      theta = sn * alpha;\n"
  "      rhobar = -cs * alpha;\n"
  "      phi = cs * phibar;\n"
  "      phibar *= sn;\n"
  "      tau = sn * phi;\n"
  "      t1 = phi / rho;\n"
  "      t2 = -theta / rho;\n"
  "      for (i=0;i<n;++i) dk[i]=ww[i]/rho;\n"
  "      for (i=0; i<n; ++i) xx[i] += t1*ww[i];\n"
  "      for (i=0; i<n; ++i) ww[i] = v[i] + t2*ww[i];\n"
  "      n2dk = casadi_norm_2(n, dk);\n"
  "      ddnorm += n2dk*n2dk;\n"
  "      delta = sn2 * rho;\n"
  "      gambar = -cs2 * rho;\n"
  "      rhs = phi - delta * z;\n"
  "      zbar = rhs / gambar;\n"
  "      xnorm = sqrt(xxnorm + zbar*zbar);\n"
  "      gamma = sqrt(gambar*gambar + theta*theta);\n"
  "      cs2 = gambar / gamma;\n"
  "      sn2 = theta / gamma;\n"
  "      z = rhs / gamma;\n"
  "      xxnorm += z*z;\n"
  "      acond = anorm * sqrt(ddnorm);\n"
  "      res1 = phibar*phibar;\n"
  "      res2 += psi*psi;\n"
  "      rnorm = sqrt(res1+res2);\n"
  "      arnorm = alpha*fabs(tau);\n"
  "      r1sq = rnorm*rnorm - dampsq * xxnorm;\n"
  "      r1norm = sqrt(fabs(r1sq));\n"
  "      if (r1sq < 0) r1norm = -r1norm;\n"
  "      test1 = rnorm / bnorm;\n"
  "      test2 = arnorm / (anorm * rnorm);\n"
  "      test3 = 1 / acond;\n"
  "      t1 = test1 / (1 + anorm * xnorm / bnorm);\n"
  "      rtol = btol + atol * anorm * xnorm / bnorm;\n"
  "      if (itn >= iter_lim) istop = 7;\n"
  "      if (1 + test3 <= 1) istop = 6;\n"
  "      if (1 + test2 <= 1) istop = 5;\n"
  "      if (1 + t1 <= 1) istop = 4;\n"
  "      if (test3 <= ctol) istop = 3;\n"
  "      if (test2 <= atol) istop = 2;\n"
  "      if (test1 <= rtol) istop = 1;\n"
  "      if (istop != 0) break;\n"
  "    }\n"
  "    casadi_copy(xx, m, x);\n"
  "    return 0;\n"
  "}\n"
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"lsqr_solve\"\n"
  "template<typename T1>\n"
  "int casadi_lsqr_solve(const T1* A, T1* x, casadi_int nrhs, casadi_int tr,\n"
  "        const casadi_int* sp, T1* w) {\n"
  "    casadi_int i;\n"
  "    for (i=0; i<nrhs;++i) {\n"
  "      if (casadi_lsqr_single_solve(A, x+i*sp[1], tr, sp, w)) return 1;\n"
  "    }\n"
  "    return 0;\n"
  "}\n";

const char* casadi_dense_lsqr_str =
  "// C-REPLACE \"fabs\" \"casadi_fabs\"\n"
  "// C-REPLACE \"sign\" \"casadi_sign\"\n"
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"lsqr_sym_ortho\"\n"
  "template<typename T1>\n"
  "void casadi_dense_lsqr_sym_ortho(T1 a, T1 b, T1* cs, T1* sn, T1* rho) {\n"
  "    T1 tau;\n"
  "    if (b == 0) {\n"
  "        *cs = sign(a);\n"
  "        *sn = 0;\n"
  "        *rho = fabs(a);\n"
  "    } else if (a==0) {\n"
  "        *cs = 0;\n"
  "        *sn = sign(b);\n"
  "        *rho = fabs(b);\n"
  "    } else if (fabs(b)>fabs(a)) {\n"
  "        tau = a/b;\n"
  "        *sn = sign(b)/sqrt(1+tau*tau);\n"
  "        *cs = (*sn)*tau;\n"
  "        *rho = b/(*sn);\n"
  "    } else {\n"
  "        tau = b/a;\n"
  "        *cs = sign(a)/sqrt(1+tau*tau);\n"
  "        *sn = (*cs)*tau;\n"
  "        *rho = a/(*cs);\n"
  "    }\n"
  "}\n"
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"lsqr_single_solve\"\n"
  "// Ref: scipy\n"
  "template<typename T1>\n"
  "int casadi_dense_lsqr_single_solve(const T1* A, T1* x, casadi_int tr, const casadi_int ncol,\n"
  "      const casadi_int nrow, T1* w) {\n"
  "    casadi_int m, n, i;\n"
  "    T1 damp, atol, btol, conlim, ctol, anorm, acond, dampsq, ddnorm, res2, xnorm, xxnorm, z;\n"
  "    T1 cs2, sn2, alpha, beta, rhobar, phibar, bnorm, rnorm, arnorm, rhobar1, cs1, sn1, psi;\n"
  "    T1 cs, sn, rho, theta, phi, tau, t1, t2, n2dk, delta, gambar, rhs, zbar, gamma, res1;\n"
  "    T1 r1sq, r1norm, test1, test2, test3, rtol;\n"
  "    casadi_int iter_lim, itn, istop;\n"
  "    T1 *u, *v, *xx, *ww, *dk;\n"
  "    m = ncol;//sp[0];\n"
  "    n = nrow;//sp[1];\n"
  "    damp = 0;\n"
  "    atol = 1e-15;\n"
  "    btol = 1e-15;\n"
  "    conlim = 1e8;\n"
  "    iter_lim = 10000;\n"
  "    itn = 0;\n"
  "    istop = 0;\n"
  "    ctol = 0;\n"
  "    if (conlim > 0) ctol = 1/conlim;\n"
  "    anorm = 0;\n"
  "    acond = 0;\n"
  "    dampsq = damp*damp;\n"
  "    ddnorm = 0;\n"
  "    res2 = 0;\n"
  "    xnorm = 0;\n"
  "    xxnorm = 0;\n"
  "    z = 0;\n"
  "    cs2 = -1;\n"
  "    sn2 = 0;\n"
  "    u = w;  w+= m; casadi_copy(x, m, u);\n"
  "    v = w;  w+= n; casadi_clear(v, n);\n"
  "    xx = w; w+= n; casadi_clear(xx, n);\n"
  "    ww = w; w+= n; casadi_clear(v, n);\n"
  "    dk = w; w+= n;\n"
  "    alpha = 0;\n"
  "    beta = casadi_norm_2(m, u);\n"
  "    if (beta>0) {\n"
  "      for (i=0;i<m;++i) u[i]*=1/beta;\n"
  "      casadi_mv_dense(A, nrow, ncol, u, v, !tr);\n"
  "      // casadi_mv(A, sp, u, v, !tr);\n"
  "      alpha = casadi_norm_2(n, v);\n"
  "    }\n"
  "    if (alpha>0) {\n"
  "      for (i=0;i<n;++i) v[i]*=1/alpha;\n"
  "      casadi_copy(v, n, ww);\n"
  "    }\n"
  "    rhobar = alpha;\n"
  "    phibar = beta;\n"
  "    bnorm = beta;\n"
  "    rnorm = beta;\n"
  "    arnorm = alpha * beta;\n"
  "    while (itn<iter_lim) {\n"
  "      itn++;\n"
  "      for (i=0;i<m;++i) u[i]*=-alpha;\n"
  "      // casadi_mv(A, sp, v, u, tr);\n"
  "      casadi_mv_dense(A, nrow, ncol, u, v, !tr);\n"
  "      beta = casadi_norm_2(m, u);\n"
  "      if (beta>0) {\n"
  "        for (i=0;i<m;++i) u[i]*=1/beta;\n"
  "        anorm = sqrt(anorm*anorm + alpha*alpha+beta*beta+damp*damp);\n"
  "        for (i=0;i<n;++i) v[i]*=-beta;\n"
  "        // casadi_mv(A, sp, u, v, !tr);\n"
  "        casadi_mv_dense(A, nrow, ncol, u, v, !tr);\n"
  "        alpha = casadi_norm_2(n, v);\n"
  "        if (alpha>0) for (i=0;i<n;++i) v[i]*=1/alpha;\n"
  "      }\n"
  "      rhobar1 = sqrt(rhobar*rhobar+damp*damp);\n"
  "      cs1 = rhobar / rhobar1;\n"
  "      sn1 = damp / rhobar1;\n"
  "      psi = sn1 * phibar;\n"
  "      phibar *= cs1;\n"
  "      casadi_dense_lsqr_sym_ortho(rhobar1, beta, &cs, &sn, &rho);\n"
  "      theta = sn * alpha;\n"
  "      rhobar = -cs * alpha;\n"
  "      phi = cs * phibar;\n"
  "      phibar *= sn;\n"
  "      tau = sn * phi;\n"
  "      t1 = phi / rho;\n"
  "      t2 = -theta / rho;\n"
  "      for (i=0;i<n;++i) dk[i]=ww[i]/rho;\n"
  "      for (i=0; i<n; ++i) xx[i] += t1*ww[i];\n"
  "      for (i=0; i<n; ++i) ww[i] = v[i] + t2*ww[i];\n"
  "      n2dk = casadi_norm_2(n, dk);\n"
  "      ddnorm += n2dk*n2dk;\n"
  "      delta = sn2 * rho;\n"
  "      gambar = -cs2 * rho;\n"
  "      rhs = phi - delta * z;\n"
  "      zbar = rhs / gambar;\n"
  "      xnorm = sqrt(xxnorm + zbar*zbar);\n"
  "      gamma = sqrt(gambar*gambar + theta*theta);\n"
  "      cs2 = gambar / gamma;\n"
  "      sn2 = theta / gamma;\n"
  "      z = rhs / gamma;\n"
  "      xxnorm += z*z;\n"
  "      acond = anorm * sqrt(ddnorm);\n"
  "      res1 = phibar*phibar;\n"
  "      res2 += psi*psi;\n"
  "      rnorm = sqrt(res1+res2);\n"
  "      arnorm = alpha*fabs(tau);\n"
  "      r1sq = rnorm*rnorm - dampsq * xxnorm;\n"
  "      r1norm = sqrt(fabs(r1sq));\n"
  "      if (r1sq < 0) r1norm = -r1norm;\n"
  "      test1 = rnorm / bnorm;\n"
  "      test2 = arnorm / (anorm * rnorm);\n"
  "      test3 = 1 / acond;\n"
  "      t1 = test1 / (1 + anorm * xnorm / bnorm);\n"
  "      rtol = btol + atol * anorm * xnorm / bnorm;\n"
  "      if (itn >= iter_lim) istop = 7;\n"
  "      if (1 + test3 <= 1) istop = 6;\n"
  "      if (1 + test2 <= 1) istop = 5;\n"
  "      if (1 + t1 <= 1) istop = 4;\n"
  "      if (test3 <= ctol) istop = 3;\n"
  "      if (test2 <= atol) istop = 2;\n"
  "      if (test1 <= rtol) istop = 1;\n"
  "      if (istop != 0) break;\n"
  "    }\n"
  "    casadi_copy(xx, m, x);\n"
  "    return 0;\n"
  "}\n"
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"lsqr_solve\"\n"
  "template<typename T1>\n"
  "int casadi_dense_lsqr_solve(const T1* A, T1* x, casadi_int nrhs, casadi_int tr,\n"
  "      const casadi_int ncol, const casadi_int nrow, T1* w) {\n"
  "    casadi_int i;\n"
  "    for (i=0; i<nrhs;++i) {\n"
  "      // if (casadi_dense_lsqr_single_solve(A, x+i*sp[1], tr, ncol, nrow, w)) return 1;\n"
  "      if (casadi_dense_lsqr_single_solve(A, x+i*nrow, tr, ncol, nrow, w)) return 1;\n"
  "    }\n"
  "    return 0;\n"
  "}\n";

const char* casadi_cache_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"cache_check\"\n"
  "template<typename T1>\n"
  "int cache_check(const T1* key, T1* cache, int* loc, casadi_int stride, casadi_int sz, casadi_int key_sz, T1** val) { // NOLINT(whitespace/line_length)\n"
  "    char match;\n"
  "    int i, c;\n"
  "    casadi_int k;\n"
  "    T1 *lkey;\n"
  "    // Walk through cache locations\n"
  "    for (i=0;i<sz;++i) {\n"
  "      match = 1;\n"
  "      if (loc[i]<0) { // Never filled\n"
  "        loc[i] = i;\n"
  "        *val = cache + i*stride;\n"
  "        break;\n"
  "      } else {\n"
  "        *val = cache + loc[i]*stride;\n"
  "        // Check for a key hit\n"
  "        lkey = *val;\n"
  "        for (k=0;k<key_sz;++k) {\n"
  "          if (lkey[k]!=key[k]) {\n"
  "            match = 0;\n"
  "            break;\n"
  "          }\n"
  "        }\n"
  "      }\n"
  "      if (match) {\n"
  "        // Move current location to front\n"
  "        c = loc[i];\n"
  "        for (k=i;k>0;--k) loc[k] = loc[k-1];\n"
  "        loc[0] = c;\n"
  "        // Indicate cache hit\n"
  "        return 1;\n"
  "      }\n"
  "    }\n"
  "    // Indicate cache miss\n"
  "    return 0;\n"
  "}\n";

const char* casadi_convexify_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"convexify_strategy_t\"\n"
  "typedef enum {\n"
  "  CVX_REGULARIZE,\n"
  "  CVX_EIGEN_CLIP,\n"
  "  CVX_EIGEN_REFLECT\n"
  "} casadi_convexify_strategy_t;\n"
  "// SYMBOL \"convexify_type_in_t\"\n"
  "typedef enum {\n"
  "  CVX_SYMM, CVX_TRIL, CVX_TRIU\n"
  "} casadi_convexify_type_in_t;\n"
  "// SYMBOL \"convexify_config\"\n"
  "template<typename T1>\n"
  "struct casadi_convexify_config {\n"
  "  casadi_convexify_strategy_t strategy;\n"
  "  casadi_convexify_type_in_t type_in;\n"
  "  const casadi_int * Hsp;\n"
  "  const casadi_int * Hrsp;\n"
  "  T1 margin;\n"
  "  // Projection of Hessian sparsity needed? (cache)\n"
  "  int Hsp_project;\n"
  "  // Reordering of Hessian needed for scc? (cache)\n"
  "  int scc_transform;\n"
  "  /// Block structure of Hessian for certain convexification methods\n"
  "  const casadi_int *scc_offset;\n"
  "  const casadi_int *scc_mapping;\n"
  "  casadi_int scc_offset_size;\n"
  "  /// For eigen-* convexification strategies: maximum iterations for symmetric Schur decomposition\n"
  "  // Needs to be \"big enough\"\n"
  "  casadi_int max_iter_eig;\n"
  "  int verbose;\n"
  "};\n"
  "// C-REPLACE \"casadi_convexify_config<T1>\" \"struct casadi_convexify_config\"\n"
  "// SYMBOL \"convexify_eval\"\n"
  "template<typename T1>\n"
  "int convexify_eval(const casadi_convexify_config<T1>* c, const T1* Hin, T1* Hout, casadi_int* iw, T1* w) { // NOLINT(whitespace/line_length)\n"
  "    casadi_int i, j, k, kk, block_size, offset;\n"
  "    int ret;\n"
  "    T1 reg, e;\n"
  "    T1 *H_block, *w_cvx;\n"
  "    casadi_int Hrsp_nnz = c->Hrsp[2+c->Hrsp[1]];\n"
  "    casadi_int nnz = c->Hsp[2+c->Hsp[1]];\n"
  "    if (c->Hsp_project) {\n"
  "      if (Hin==Hout) {\n"
  "        casadi_copy(Hin, Hrsp_nnz, w);\n"
  "        casadi_project(w, c->Hrsp, Hout, c->Hsp, w+Hrsp_nnz);\n"
  "      } else {\n"
  "        casadi_project(Hin, c->Hrsp, Hout, c->Hsp, w);\n"
  "      }\n"
  "    } else {\n"
  "      if (Hin!=Hout) casadi_copy(Hin, nnz, Hout);\n"
  "    }\n"
  "    if (c->strategy==CVX_REGULARIZE) {\n"
  "      // Determine regularization parameter with Gershgorin theorem\n"
  "      reg = c->margin-casadi_lb_eig(c->Hsp, Hout);\n"
  "      if (reg > 0) casadi_regularize(c->Hsp, Hout, reg);\n"
  "    } else if (c->strategy==CVX_EIGEN_REFLECT || c->strategy==CVX_EIGEN_CLIP) {\n"
  "      offset = 0;\n"
  "      // Loop over Hessian blocks\n"
  "      for (k=0;k<c->scc_offset_size-1;++k) {\n"
  "        block_size = c->scc_offset[k+1]-c->scc_offset[k];\n"
  "        H_block = w;\n"
  "        w_cvx = w;\n"
  "        // Set w_cvx to dense Hessian block from Hout\n"
  "        if (c->scc_transform) {\n"
  "          kk=0;\n"
  "          if (c->type_in==CVX_SYMM) {\n"
  "            // Loop over columns of block\n"
  "            for (i=0;i<block_size;++i) {\n"
  "              // Loop over elements in column\n"
  "              for (j=0;j<block_size;++j, ++kk) {\n"
  "                H_block[kk] = Hout[c->scc_mapping[offset+kk]];\n"
  "              }\n"
  "            }\n"
  "          } else if (c->type_in==CVX_TRIU) {\n"
  "            // Loop over columns of block\n"
  "            for (i=0;i<block_size;++i) {\n"
  "              // Loop over elements in column\n"
  "              for (j=0;j<i+1;++j, ++kk) {\n"
  "                  e = Hout[c->scc_mapping[offset+kk]];\n"
  "                  H_block[i*block_size+j] = e;\n"
  "                  H_block[i+block_size*j] = e;\n"
  "              }\n"
  "            }\n"
  "          } else {\n"
  "            // Loop over columns of block\n"
  "            for (i=0;i<block_size;++i) {\n"
  "              for (j=i;j<block_size;++j, ++kk) {\n"
  "                e = Hout[c->scc_mapping[offset+kk]];\n"
  "                H_block[i*block_size+j] = e;\n"
  "                H_block[i+block_size*j] = e;\n"
  "              }\n"
  "            }\n"
  "          }\n"
  "          w_cvx += block_size*block_size;\n"
  "        } else {\n"
  "          H_block = Hout+offset;\n"
  "        }\n"
  "        // Perform convexification\n"
  "        ret = casadi_cvx(block_size, H_block, c->margin, 1e-10,\n"
  "          c->strategy==CVX_EIGEN_REFLECT, c->max_iter_eig, w_cvx, iw);\n"
  "        if (ret) return ret;\n"
  "        // Fill in upper-rectangular part\n"
  "        for (i=0;i<block_size;++i) {\n"
  "          for (j=0;j<i+1;++j) {\n"
  "            H_block[block_size*i+j] = H_block[block_size*j+i];\n"
  "          }\n"
  "        }\n"
  "        // Put results back in Hout\n"
  "        if (c->scc_transform) {\n"
  "          kk=0;\n"
  "          if (c->type_in==CVX_SYMM) {\n"
  "            // Loop over columns of block\n"
  "            for (i=0;i<block_size;++i) {\n"
  "              // Loop over elements in column\n"
  "              for (j=0;j<block_size;++j, ++kk) {\n"
  "                Hout[c->scc_mapping[offset+kk]] = H_block[kk];\n"
  "              }\n"
  "            }\n"
  "          } else if (c->type_in==CVX_TRIU) {\n"
  "            // Loop over columns of block\n"
  "            for (i=0;i<block_size;++i) {\n"
  "              // Loop over elements in column\n"
  "              for (j=0;j<i+1;++j, ++kk) {\n"
  "                Hout[c->scc_mapping[offset+kk]] = H_block[block_size*i+j];\n"
  "              }\n"
  "            }\n"
  "          } else {\n"
  "            // Loop over columns of block\n"
  "            for (i=0;i<block_size;++i) {\n"
  "              // Loop over elements in column\n"
  "              for (j=i;j<block_size;++j, ++kk) {\n"
  "                Hout[c->scc_mapping[offset+kk]] = H_block[block_size*i+j];\n"
  "              }\n"
  "            }\n"
  "          }\n"
  "        }\n"
  "        if (c->type_in==CVX_SYMM) {\n"
  "          offset += block_size*block_size;\n"
  "        } else {\n"
  "          offset += block_size*(block_size+1)/2;\n"
  "        }\n"
  "      }\n"
  "    }\n"
  "    return 0;\n"
  "  }\n";

const char* casadi_logsumexp_str =
  "//\n"
  "//    MIT No Attribution\n"
  "//\n"
  "//    Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n"
  "//\n"
  "//    Permission is hereby granted, free of charge, to any person obtaining a copy of this\n"
  "//    software and associated documentation files (the \"Software\"), to deal in the Software\n"
  "//    without restriction, including without limitation the rights to use, copy, modify,\n"
  "//    merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n"
  "//    permit persons to whom the Software is furnished to do so.\n"
  "//\n"
  "//    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n"
  "//    INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n"
  "//    PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n"
  "//    HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n"
  "//    OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n"
  "//    SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n"
  "//\n"
  "// SYMBOL \"logsumexp\"\n"
  "template<typename T1>\n"
  "T1 casadi_logsumexp(const T1* x, casadi_int n) {\n"
  "  casadi_int i, max_ind;\n"
  "  T1 max, r;\n"
  "  if (n==1) return x[0];\n"
  "  max_ind = 0;\n"
  "  max = x[0];\n"
  "  // Determine max, argmax\n"
  "  for (i=1; i<n; ++i) {\n"
  "    if (x[i]>x[0]) {\n"
  "      max = x[i];\n"
  "      max_ind = i;\n"
  "    }\n"
  "  }\n"
  "  r = 0;\n"
  "  for (i=0; i<n; ++i) {\n"
  "    if (i!=max_ind) r += exp(x[i]-max);\n"
  "  }\n"
  "  // C-REPLACE \"log1p\" \"casadi_log1p\"\n"
  "  return log1p(r)+max;\n"
  "}\n";

